import{c as x,l as y}from"./chunk-_AdZ4IJm.js";import{_ as Fv}from"./main-ZJZ6WBO4.js";function w(o,a){return{data:{labels:o.data.labels.map(n=>Array.isArray(n)?n.map(r=>Fv(r,a)):Fv(n,a)),datasets:o.data.datasets.map(n=>y(x({},n),{label:Fv(n.label,a)}))},options:o.options(a)}}var t={bigserial:`hsl(240 5% 26%)`,uuidv7:`hsl(220 70% 55%)`,uuid4:`hsl(0 0% 75%)`,node:`hsl(96 38% 42%)`,nodeAlt:`hsl(96 22% 68%)`,rust:`hsl(18 78% 48%)`,wlSieve:`#3C71DD`,wlLoop:`#DA541B`,wlHash:`#8E63C9`,neutral:`hsl(240 5% 26%)`,neutralAlt:`hsl(240 4% 65%)`};function u(o){return{responsive:!0,maintainAspectRatio:!1,devicePixelRatio:Math.max(5,(typeof window>`u`?5:window.devicePixelRatio)||5),resizeDelay:0,plugins:{legend:{position:`bottom`,labels:{usePointStyle:!0,pointStyle:`circle`,padding:20,font:{family:`Inter, system-ui, sans-serif`,size:12}}},tooltip:{backgroundColor:`hsl(0 0% 98%)`,titleColor:`hsl(240 10% 10%)`,bodyColor:`hsl(240 5% 26%)`,borderColor:`hsl(0 0% 90%)`,borderWidth:1,cornerRadius:8,padding:10,titleFont:{family:`Inter, system-ui, sans-serif`,size:13,weight:`bold`},bodyFont:{family:`Inter, system-ui, sans-serif`,size:12}}},scales:{x:{grid:{display:!1},border:{display:!1},ticks:{font:{family:`Inter, system-ui, sans-serif`,size:12},color:`hsl(240 5% 46%)`}},y:{grid:{color:`hsl(0 0% 93%)`},border:{display:!1},ticks:{font:{family:`Inter, system-ui, sans-serif`,size:11},color:`hsl(240 5% 46%)`,callback:a=>a+o}}}}}function s(o){return a=>u(Fv(o,a))}function e(o,a,n){return{label:o,data:a,backgroundColor:n,borderRadius:6,barPercentage:.6}}function m(o,a,n=0){return r=>{let i=u(Fv(o,r));return y(x({},i),{scales:y(x({},i.scales),{y:y(x({},i.scales.y),{suggestedMax:n,grid:{color:c=>c.tick?.value===a?`hsl(240 5% 46%)`:`hsl(0 0% 93%)`,lineWidth:c=>c.tick?.value===a?2:1}})})})}}function b(){return o=>{let a=u(``),n=[1e6,1e7,1e8,1e9,1e10];return y(x({},a),{indexAxis:`y`,scales:{x:{type:`logarithmic`,min:1e6,max:1e10,grid:{color:r=>r.tick?.value===1e8?`hsl(240 5% 46%)`:n.includes(r.tick?.value)?`hsl(0 0% 93%)`:`transparent`,lineWidth:r=>r.tick?.value===1e8?2:1},border:{display:!1},ticks:{font:{family:`Inter, system-ui, sans-serif`,size:11},color:r=>r.tick?.value===1e8?`hsl(240 10% 10%)`:`hsl(240 5% 46%)`,autoSkip:!1,maxRotation:0,callback:r=>{let i=Number(r);if(!n.includes(i))return``;if(i===1e8)return o===`zh`?`10⁸（規則）`:`10⁸ (the rule)`;let c=`⁰¹²³⁴⁵⁶⁷⁸⁹`;return 10+String(Math.round(Math.log10(i))).split(``).map(p=>c[+p]).join(``)}}},y:{grid:{display:!1},border:{display:!1},ticks:{font:{family:`Inter, system-ui, sans-serif`,size:12},color:`hsl(240 5% 46%)`}}}})}}var v=[{id:`uuid-primary-key`,title:`UUID Primary Key: BIGSERIAL vs UUID v4 vs UUIDv7`,date:`2026-03-20`,env:{zh:`PostgreSQL 17.9 (Postgres.app), macOS (M1 Pro), local SSD。2026-07-31 全項重測：迴圈類取 5 次中位數，bulk insert 取 3 次中位數，SELECT/Range 計時前先跑一輪 warm-up。UUIDv7 由 pg_uuidv7 extension（C 實作）生成，PostgreSQL 18 才有原生 uuidv7()`,en:`PostgreSQL 17.9 (Postgres.app), macOS (M1 Pro), local SSD. All items re-measured on 2026-07-31: loop items take the median of 5 runs, bulk insert takes the median of 3 runs, SELECT/Range runs one warm-up round before timing. UUIDv7 is generated by the pg_uuidv7 extension (C implementation); native uuidv7() only arrives in PostgreSQL 18`},summary:{zh:`BIGSERIAL、UUID v4、UUIDv7 三種 primary key 的 INSERT 速度、index 大小、SELECT、range query 完整比較。UUID v4 在 range query 時差距最大。`,en:`A full comparison of three primary keys, BIGSERIAL, UUID v4 and UUIDv7: INSERT speed, index size, SELECT and range query. UUID v4 falls furthest behind on range query.`},charts:[{subtitle:`INSERT 1M Rows`,description:{zh:`100 萬筆 INSERT。BIGSERIAL 和 UUIDv7 都是 sequential write，UUID v4 是 random write。`,en:`INSERT of 1 million rows. BIGSERIAL and UUIDv7 are both sequential writes, UUID v4 is a random write.`},sql:`-- Setup
CREATE SCHEMA bench;
CREATE TABLE bench.t_serial (id BIGSERIAL PRIMARY KEY, payload TEXT);
CREATE TABLE bench.t_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payload TEXT);
-- UUIDv7 is generated with the pg_uuidv7 extension (C implementation). PG 17 has no native uuidv7(),
-- so build the dylib from source, then register it with CREATE FUNCTION pointing at the absolute path:
-- CREATE FUNCTION uuid_generate_v7() RETURNS uuid
--   AS '/path/to/pg_uuidv7.dylib', 'uuid_generate_v7' LANGUAGE C VOLATILE;
CREATE TABLE bench.t_uuid7 (id UUID PRIMARY KEY DEFAULT uuid_generate_v7(), payload TEXT);

-- BIGSERIAL
\\timing on
INSERT INTO bench.t_serial (payload)
SELECT 'row-' || i FROM generate_series(1, 1000000) AS i;

-- UUID v4
INSERT INTO bench.t_uuid4 (payload)
SELECT 'row-' || i FROM generate_series(1, 1000000) AS i;

-- UUIDv7
INSERT INTO bench.t_uuid7 (payload)
SELECT 'row-' || i FROM generate_series(1, 1000000) AS i;`,chart:{type:`bar`,data:{labels:[`INSERT 1M rows`],datasets:[e(`BIGSERIAL`,[2.7],t.bigserial),e(`UUIDv7`,[3.5],t.uuidv7),e(`UUID v4`,[4.5],t.uuid4)]},options:s(`s`)},conclusion:{zh:`UUID v4 比 BIGSERIAL 慢 1.7 倍，UUIDv7 居中。UUIDv7 有時間順序，寫入落點跟 BIGSERIAL 一樣集中，但 128-bit 的 index 仍然比 64-bit BIGINT 大。資料量上去差距會拉開：從 1M 補到 5M（一次插 400 萬筆），BIGSERIAL 10.2s、UUIDv7 15.5s、UUID v4 19.5s。index 越大，random insert 要碰的 page 就越分散。`,en:`UUID v4 is 1.7 times slower than BIGSERIAL, UUIDv7 sits in between. UUIDv7 is time ordered, so its writes land as tightly as BIGSERIAL, but the 128-bit index is still larger than 64-bit BIGINT. The gap widens as data grows: filling from 1M to 5M (4 million rows in one insert) takes BIGSERIAL 10.2s, UUIDv7 15.5s, UUID v4 19.5s. The larger the index, the more scattered the pages a random insert has to touch.`}},{subtitle:`Index Size at 1M and 5M`,description:{zh:`Primary key index 佔用的磁碟空間。UUID 是 128-bit，BIGINT 是 64-bit，index entry 大一倍。`,en:`Disk space taken by the primary key index. UUID is 128-bit, BIGINT is 64-bit, so an index entry is twice as large.`},sql:`-- Check index + table size
SELECT
  t.tablename,
  pg_size_pretty(pg_relation_size(i.indexrelid)) AS index_size,
  pg_size_pretty(pg_relation_size(c.oid)) AS table_size
FROM pg_tables t
JOIN pg_class c ON c.relname = t.tablename
JOIN pg_index i ON i.indrelid = c.oid AND i.indisprimary
WHERE t.schemaname = 'bench'
ORDER BY t.tablename;`,chart:{type:`bar`,data:{labels:[`1M rows`,`5M rows`],datasets:[e(`BIGSERIAL`,[21,107],t.bigserial),e(`UUIDv7`,[38,201],t.uuidv7),e(`UUID v4`,[37,190],t.uuid4)]},options:s(` MB`)},conclusion:{zh:`UUID index 大約是 BIGINT 的 1.8 倍。Index 越大，buffer pool 能裝的 page 越少，越容易碰磁碟。`,en:`The UUID index is about 1.8 times the BIGINT one. The larger the index, the fewer pages the buffer pool can hold, and the more often reads hit disk.`}},{subtitle:`SELECT by PK x1000`,description:{zh:`隨機撈 1000 個已存在的 ID，逐筆 <code>SELECT WHERE id = ?</code>。測試 B+ tree 點查效能。`,en:`Pick 1000 existing IDs at random and run <code>SELECT WHERE id = ?</code> one by one. Tests B+ tree point lookup performance.`},sql:`-- BIGSERIAL
DO $$
DECLARE
  _ids BIGINT[];
  _id BIGINT;
  _s TIMESTAMP; _e TIMESTAMP;
BEGIN
  SELECT array_agg(id) INTO _ids
  FROM (SELECT id FROM bench.t_serial ORDER BY random() LIMIT 1000) t;
  _s := clock_timestamp();
  FOR i IN 1..1000 LOOP
    SELECT id INTO _id FROM bench.t_serial WHERE id = _ids[i];
  END LOOP;
  _e := clock_timestamp();
  RAISE NOTICE 'BIGSERIAL SELECT x1000: %', _e - _s;
END $$;

-- UUID v4 (same pattern, replace table + type)
DO $$
DECLARE
  _ids UUID[];
  _id UUID;
  _s TIMESTAMP; _e TIMESTAMP;
BEGIN
  SELECT array_agg(id) INTO _ids
  FROM (SELECT id FROM bench.t_uuid4 ORDER BY random() LIMIT 1000) t;
  _s := clock_timestamp();
  FOR i IN 1..1000 LOOP
    SELECT id INTO _id FROM bench.t_uuid4 WHERE id = _ids[i];
  END LOOP;
  _e := clock_timestamp();
  RAISE NOTICE 'UUID v4 SELECT x1000: %', _e - _s;
END $$;`,chart:{type:`bar`,data:{labels:[`1M rows`,`5M rows`],datasets:[e(`BIGSERIAL`,[7,74],t.bigserial),e(`UUIDv7`,[8,86],t.uuidv7),e(`UUID v4`,[12,89],t.uuid4)]},options:s(` ms`)},conclusion:{zh:`1M 時整個 index 都在 cache 裡，三者都是個位數 ms（單次點查幾微秒），差距在雜訊等級。5M 時 index 超過 shared_buffers（128MB），三者一起變慢，BIGSERIAL 略快：64-bit index 只有 UUID 的一半大，留在記憶體裡的比例高。這一項對 cache 狀態很敏感，同一組設定重複量會在 ±30% 內跳，只能當量級看。`,en:`At 1M the whole index sits in cache, all three are in the single digits of ms (a few microseconds per lookup), and the gap is at noise level. At 5M the index exceeds shared_buffers (128MB), all three slow down together, and BIGSERIAL is slightly faster: the 64-bit index is half the size of UUID, so a larger share of it stays in memory. This item is sensitive to cache state. Repeating the same setup jumps within ±30%, so read it as an order of magnitude only.`}},{subtitle:`Range Query x1000`,description:{zh:`<code>WHERE id &gt;= ? ORDER BY id LIMIT 100</code>，重複 1000 次。測試 B+ tree leaf scan 和 page 碎片化。`,en:`<code>WHERE id &gt;= ? ORDER BY id LIMIT 100</code>, repeated 1000 times. Tests B+ tree leaf scan and page fragmentation.`},sql:`-- BIGSERIAL
DO $$
DECLARE
  _ids BIGINT[];
  _count INT;
  _s TIMESTAMP; _e TIMESTAMP;
BEGIN
  SELECT array_agg(id) INTO _ids
  FROM (SELECT id FROM bench.t_serial TABLESAMPLE SYSTEM(1) LIMIT 1000) t;
  _s := clock_timestamp();
  FOR i IN 1..1000 LOOP
    SELECT count(*) INTO _count FROM (
      SELECT id FROM bench.t_serial WHERE id >= _ids[i] ORDER BY id LIMIT 100
    ) sub;
  END LOOP;
  _e := clock_timestamp();
  RAISE NOTICE 'BIGSERIAL range x1000: %', _e - _s;
END $$;

-- UUID v4 (same pattern, replace table + type)`,chart:{type:`bar`,data:{labels:[`1M rows`,`5M rows`],datasets:[e(`BIGSERIAL`,[14,10],t.bigserial),e(`UUIDv7`,[17,9],t.uuidv7),e(`UUID v4`,[43,105],t.uuid4)]},options:s(` ms`)},conclusion:{zh:`Range query 是三種 PK 差距最大的一項。BIGSERIAL 和 UUIDv7 在兩個資料量都是 10 到 17ms，UUID v4 從 43ms 漲到 105ms：random insert 造成的 page 碎片化在 range scan 時被放大，資料越多越明顯。修正紀錄：舊版這格 BIGSERIAL 在 1M 顯示 96ms，是當時起點取法不對稱的殘留（BIGSERIAL 用 random 算起點、UUID 抽真實 ID）；這次三組同法（都用 TABLESAMPLE 抽真實 ID 當起點）重測，異常消失。`,en:`Range query is where the three PKs differ most. BIGSERIAL and UUIDv7 are 10 to 17ms at both data sizes, UUID v4 grows from 43ms to 105ms: the page fragmentation caused by random inserts is amplified in a range scan, and the more data, the clearer it gets. Correction note: the old version showed BIGSERIAL at 96ms for 1M in this cell. That was a leftover of an asymmetric choice of start points (BIGSERIAL computed its start point with random, UUID sampled real IDs). This round all three groups use the same method (TABLESAMPLE picks real IDs as start points), and the anomaly is gone.`}},{subtitle:{zh:`Cold Start（5M rows，兩層 cache 全清）`,en:`Cold Start (5M rows, both cache layers cleared)`},description:{zh:`前面的讀取測項都是暖 cache 之後量的穩態。這組量的是反面，也就是 failover、重開機、deploy 之後第一波流量遇到的狀態。冷要冷兩層：重啟 Postgres 清 shared_buffers，再用 <code>sudo purge</code> 清 macOS 的檔案 cache，少清一層都只是半冷。每量一組設定就重新冷一次，因為冷是一次性的，量完第一輪就暖了。樣本 ID 在暖態先抽好存表，臨場抽會把整張表掃暖。量測順序每輪輪換，每組 5 輪取中位數。`,en:`The read items above measure the steady state after the cache is warm. This group measures the opposite: the state the first wave of traffic meets after a failover, a reboot or a deploy. Cold means cold on two layers: restart Postgres to clear shared_buffers, then run <code>sudo purge</code> to clear the macOS file cache. Skip one layer and it is only half cold. Every setup is made cold again before it is measured, because cold is a one time state: after the first round it is warm. The sample IDs are picked and stored in a table while warm, because picking them on the spot would scan the whole table warm. The measurement order rotates every round, and each setup takes the median of 5 rounds.`},lang:`raw`,codeLabel:{zh:`指令`,en:`Commands`},sql:`\`\`\`bash
# Before each measurement:
pg_ctl -D "$DATADIR" stop -m fast -w
sudo purge                       # clear the macOS file cache, as if just booted
pg_ctl -D "$DATADIR" start -w
# Then measure one group only (1000 point lookups or 1000 range scans),
# reading IDs from bench.cold_samples picked in advance, never touching the big table
\`\`\``,chart:{type:`bar`,data:{labels:[`Point lookup x1000`,`Range x1000`],datasets:[e(`BIGSERIAL`,[151,172],t.bigserial),e(`UUIDv7`,[168,223],t.uuidv7),e(`UUID v4`,[164,239],t.uuid4)]},options:s(` ms`)},conclusion:{zh:`冷的代價比 PK 的差距大：暖測 range 是 9.7ms（BIGSERIAL）對 105ms（UUID v4）的 10 倍差距，冷測變成 172 對 239ms，縮到 1.4 倍。15 倍上下的冷代價三種 PK 都要付，這部分遠大於彼此的差別。預測落空的紀錄：我原本押 UUID v4 的碎片化在冷測會更誇張，結果沒有。這條 range query 只撈 id（PK 本身），Postgres 走 index-only scan，從頭到尾不碰 heap，所以 heap 的碎片化不影響成本；100 筆連續 key 不管哪種 PK 都擠在少數幾個 leaf page，冷讀次數差不多。如果 SELECT 撈的是其他欄位，每筆都要回 heap，碎片化才會回到成本裡。五輪數字穩定在 1% 內，Apple NVMe 的隨機讀又快又穩，也是差距拉不開的另一半原因。`,en:`The cost of cold is larger than the gap between PKs: the warm range test was a 10x gap, 9.7ms (BIGSERIAL) against 105ms (UUID v4); the cold test is 172 against 239ms, down to 1.4x. All three PKs pay a cold cost of around 15x, and that part is far larger than the difference between them. A failed prediction, on record: I bet that UUID v4 fragmentation would look even worse in the cold test. It did not. This range query selects only id (the PK itself), so Postgres uses an index-only scan and never touches the heap, and heap fragmentation does not enter the cost. 100 consecutive keys sit in a few leaf pages whichever PK is used, so the number of cold reads is about the same. If the SELECT fetched other columns, every row would go back to the heap, and fragmentation would return to the cost. The five rounds are stable within 1%. Random reads on Apple NVMe are fast and steady, which is the other half of why the gap stays small.`}},{subtitle:`Single vs Batch INSERT (10,000 rows)`,description:{zh:`逐筆 INSERT loop vs 一次 batch INSERT。測試 per-statement overhead。`,en:`Row by row INSERT loop vs one batch INSERT. Tests per-statement overhead.`},sql:`-- Setup
CREATE TABLE bench.t_single_serial (id BIGSERIAL PRIMARY KEY, payload TEXT);
CREATE TABLE bench.t_single_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payload TEXT);
CREATE TABLE bench.t_batch_serial (id BIGSERIAL PRIMARY KEY, payload TEXT);
CREATE TABLE bench.t_batch_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payload TEXT);

-- Single INSERT x10000 (BIGSERIAL)
DO $$
DECLARE _s TIMESTAMP; _e TIMESTAMP;
BEGIN
  _s := clock_timestamp();
  FOR i IN 1..10000 LOOP
    INSERT INTO bench.t_single_serial (payload) VALUES ('row-' || i);
  END LOOP;
  _e := clock_timestamp();
  RAISE NOTICE 'single x10000: %', _e - _s;
END $$;

-- Batch INSERT 10000 (BIGSERIAL)
\\timing on
INSERT INTO bench.t_batch_serial (payload)
SELECT 'row-' || i FROM generate_series(1, 10000) AS i;`,chart:{type:`bar`,data:{labels:[`Single x10000`,`Batch 10000`],datasets:[e(`BIGSERIAL`,[23,10],t.bigserial),e(`UUID v4`,[29,15],t.uuid4)]},options:s(` ms`)},conclusion:{zh:`Batch 比 single 快約 2 倍（省掉 per-statement overhead；這裡整個 loop 在同一個 transaction 裡，如果每筆各自 commit，差距會更大）。BIGSERIAL 和 UUID v4 在 1 萬筆等級只差幾 ms，index 全在記憶體裡。`,en:`Batch is about 2 times faster than single (it skips the per-statement overhead; here the whole loop runs in one transaction, and if each row committed on its own the gap would be larger). BIGSERIAL and UUID v4 differ by only a few ms at the 10,000 row level, the index is entirely in memory.`}},{subtitle:`Concurrent Write (4 connections x 25,000)`,description:{zh:`4 條 connection 同時 INSERT，共 10 萬筆。測試 leaf page lock contention。`,en:`4 connections INSERT at the same time, 100,000 rows in total. Tests leaf page lock contention.`},sql:`-- Setup
CREATE TABLE bench.t_conc_serial (id BIGSERIAL PRIMARY KEY, payload TEXT);
CREATE TABLE bench.t_conc_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payload TEXT);

-- Run in shell (4 parallel psql processes)
# BIGSERIAL
time (
  for i in 1 2 3 4; do
    psql -c "INSERT INTO bench.t_conc_serial (payload) \\
      SELECT 'conn\${i}-' || g FROM generate_series(1, 25000) AS g;" &
  done
  wait
)

# UUID v4
time (
  for i in 1 2 3 4; do
    psql -c "INSERT INTO bench.t_conc_uuid4 (payload) \\
      SELECT 'conn\${i}-' || g FROM generate_series(1, 25000) AS g;" &
  done
  wait
)

# UUIDv7: same pattern, id generated by DEFAULT uuid_generate_v7()`,chart:{type:`bar`,data:{labels:[`4 connections x 25,000`],datasets:[e(`BIGSERIAL`,[245],t.bigserial),e(`UUIDv7`,[292],t.uuidv7),e(`UUID v4`,[224],t.uuid4)]},options:s(` ms`)},conclusion:{zh:`UUID v4 反而最快。Sequential 型的兩個（BIGSERIAL、UUIDv7）的 4 條 connection 全部搶同一個最右邊的 leaf page，產生 lock contention；UUID v4 寫到不同 page，不搶鎖。Concurrent write 是 sequential ID 少數會輸的場景，而 UUIDv7 因為 timestamp 前綴也是往最右邊 append，把這個弱點一起繼承了。修正紀錄：前一版把 UUIDv7 比 BIGSERIAL 更慢的部分歸給 SQL 模擬生成的成本，換成 C 實作的 uuid_generate_v7() 重測後 v7 還是慢一截（292 對 245ms），那個解釋不成立；剩下的差距沒有往下追。這一場在有背景負載的機器上量（load average 5 上下），三輪的分佈不小，倍率當量級看。`,en:`UUID v4 is the fastest here. For the two sequential types (BIGSERIAL, UUIDv7), all 4 connections compete for the same rightmost leaf page, which causes lock contention; UUID v4 writes to different pages and does not compete for the lock. Concurrent write is one of the few scenarios where a sequential ID loses, and UUIDv7 inherits this weakness because its timestamp prefix also appends at the rightmost end. Correction note: the previous version blamed the part where UUIDv7 is slower than BIGSERIAL on the cost of generating it in SQL. After switching to the C implementation uuid_generate_v7() and re-measuring, v7 is still clearly slower (292 against 245ms), so that explanation does not hold; the remaining gap was not chased further. This run was measured on a machine with background load (load average around 5), the three rounds spread quite a bit, so read the ratio as an order of magnitude.`}},{subtitle:{zh:`DELETE 50% + Re-INSERT（碎片化）`,en:`DELETE 50% + Re-INSERT (fragmentation)`},description:{zh:`1M rows 刪掉一半，再補回 50 萬筆。測試 table/index bloat。PostgreSQL 的 DELETE 不會真的刪資料，只是標記 dead row。`,en:`Delete half of 1M rows, then refill 500,000 rows. Tests table/index bloat. DELETE in PostgreSQL does not really remove data, it only marks dead rows.`},sql:`-- Copy 1M rows for the test
CREATE TABLE bench.t_frag_serial AS SELECT * FROM bench.t_serial LIMIT 1000000;
ALTER TABLE bench.t_frag_serial ADD PRIMARY KEY (id);
CREATE TABLE bench.t_frag_uuid4 AS SELECT * FROM bench.t_uuid4 LIMIT 1000000;
ALTER TABLE bench.t_frag_uuid4 ADD PRIMARY KEY (id);

-- DELETE 50%
DELETE FROM bench.t_frag_serial WHERE random() < 0.5;
DELETE FROM bench.t_frag_uuid4 WHERE random() < 0.5;

-- Re-INSERT 500K
INSERT INTO bench.t_frag_serial (id, payload)
SELECT 5000001 + i, 'refill-' || i FROM generate_series(1, 500000) AS i;

INSERT INTO bench.t_frag_uuid4 (id, payload)
SELECT gen_random_uuid(), 'refill-' || i FROM generate_series(1, 500000) AS i;

-- Check bloat
SELECT relname,
  pg_size_pretty(pg_relation_size(schemaname || '.' || relname)) AS table_size
FROM pg_stat_user_tables WHERE relname LIKE 't_frag%';`,chart:{type:`bar`,data:{labels:[{zh:`Index 改前`,en:`Index before`},{zh:`Index 改後`,en:`Index after`}],datasets:[e(`BIGSERIAL`,[21,32],t.bigserial),e(`UUIDv7`,[30,50],t.uuidv7),e(`UUID v4`,[30,60],t.uuid4)]},options:s(` MB`)},conclusion:{zh:`UUID v4 index 膨脹 100%（30→60 MB），UUIDv7 膨脹 65%（30→50 MB），BIGSERIAL 膨脹 50%（21→32 MB）。Re-INSERT 速度：BIGSERIAL 1.2s、UUIDv7 1.8s、UUID v4 3.0s。UUIDv7 介於兩者之間，明顯好過 UUID v4。`,en:`The UUID v4 index bloats 100% (30→60 MB), UUIDv7 bloats 65% (30→50 MB), BIGSERIAL bloats 50% (21→32 MB). Re-INSERT speed: BIGSERIAL 1.2s, UUIDv7 1.8s, UUID v4 3.0s. UUIDv7 sits between the two and is clearly better than UUID v4.`}},{subtitle:{zh:`Secondary Index 數量（0 vs 3 個，500K rows）`,en:`Secondary Index count (0 vs 3, 500K rows)`},description:{zh:`同一張表加 3 個 secondary index（status, created_at, payload），測試 INSERT 變慢多少。`,en:`Add 3 secondary indexes (status, created_at, payload) to the same table, and test how much slower INSERT gets.`},sql:`-- 0 secondary indexes
CREATE TABLE bench.t_idx0_serial (id BIGSERIAL PRIMARY KEY, payload TEXT, status TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE bench.t_idx0_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payload TEXT, status TEXT, created_at TIMESTAMP DEFAULT now());

-- 3 secondary indexes
CREATE TABLE bench.t_idx3_serial (id BIGSERIAL PRIMARY KEY, payload TEXT, status TEXT, created_at TIMESTAMP DEFAULT now());
CREATE INDEX idx3_serial_status ON bench.t_idx3_serial(status);
CREATE INDEX idx3_serial_created ON bench.t_idx3_serial(created_at);
CREATE INDEX idx3_serial_payload ON bench.t_idx3_serial(payload);
-- UUID v4 the same way

\\timing on
INSERT INTO bench.t_idx0_serial (payload, status)
SELECT 'row-' || i, CASE WHEN random() < 0.5 THEN 'active' ELSE 'inactive' END
FROM generate_series(1, 500000) AS i;`,chart:{type:`bar`,data:{labels:[`0 secondary index`,`3 secondary indexes`],datasets:[e(`BIGSERIAL`,[1.6,6.2],t.bigserial),e(`UUIDv7`,[2.1,6.5],t.uuidv7),e(`UUID v4`,[2.3,7.2],t.uuid4)]},options:s(`s`)},conclusion:{zh:`Secondary index 讓 INSERT 變慢 3 到 4 倍。三者在加 index 後的差距縮小（BIGSERIAL 6.2s、UUIDv7 6.5s、UUID v4 7.2s，只差 16%），因為瓶頸從 PK index 轉移到 secondary index 的維護成本。`,en:`Secondary indexes make INSERT 3 to 4 times slower. The gap between the three shrinks after the indexes are added (BIGSERIAL 6.2s, UUIDv7 6.5s, UUID v4 7.2s, only 16% apart), because the bottleneck moves from the PK index to the cost of maintaining the secondary indexes.`}},{subtitle:{zh:`JSONB Column（500K rows）`,en:`JSONB Column (500K rows)`},description:{zh:`每筆帶一個 JSONB 欄位（name, email, settings, tags）。測試大 row 是否稀釋 PK 格式的影響。`,en:`Every row carries one JSONB column (name, email, settings, tags). Tests whether a large row dilutes the effect of the PK format.`},sql:`CREATE TABLE bench.t_json_serial (id BIGSERIAL PRIMARY KEY, data JSONB);
CREATE TABLE bench.t_json_uuid4 (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), data JSONB);

\\timing on
INSERT INTO bench.t_json_serial (data)
SELECT jsonb_build_object(
  'name', 'user-' || i,
  'email', 'user' || i || '@example.com',
  'settings', jsonb_build_object('theme', 'dark', 'lang', 'zh-TW', 'notifications', true),
  'tags', jsonb_build_array('tag-' || (i % 10), 'tag-' || (i % 20))
) FROM generate_series(1, 500000) AS i;`,chart:{type:`bar`,data:{labels:[`INSERT 500K with JSONB`],datasets:[e(`BIGSERIAL`,[3.7],t.bigserial),e(`UUIDv7`,[4],t.uuidv7),e(`UUID v4`,[4.5],t.uuid4)]},options:s(`s`)},conclusion:{zh:`三者差距在 20% 以內。Row 越大，page split 的成本主要來自 data 本身，PK 格式的影響被稀釋。如果表的 row 本來就大（帶 JSONB、TEXT），PK 選哪種影響不大。修正紀錄：舊版寫「UUIDv7 略慢於 UUID v4」，重測兩輪都反過來（4.0s 對 4.5s），差距在雜訊邊緣，那個宣稱站不住，撤掉。`,en:`The three are within 20% of each other. The larger the row, the more the cost of a page split comes from the data itself, and the effect of the PK format is diluted. If the table rows are already large (with JSONB, TEXT), the choice of PK matters little. Correction note: the old version said "UUIDv7 is slightly slower than UUID v4". Two re-measured rounds both came out the other way (4.0s against 4.5s), the gap is at the edge of noise, so that claim does not hold and is withdrawn.`}}]},{id:`rust-vs-v8`,title:{zh:`Rust vs V8: 把「Rust 比 JavaScript 快」拆開來量`,en:`Rust vs V8: taking "Rust is faster than JavaScript" apart and measuring each piece`},date:`2026-07-20`,env:{zh:`Apple M1 Pro (arm64), Node v22.22.3, rustc 1.97.1, Rust 全部 -C opt-level=3`,en:`Apple M1 Pro (arm64), Node v22.22.3, rustc 1.97.1, all Rust built with -C opt-level=3`},summary:{zh:`在同一台機器上，把「Rust 比較快」拆成十幾種情況分開量。結果從 Node 比較快、兩邊平手，到 Rust 快 35 倍都有。最後拿 Babel、SWC、esbuild 三個真的工具來比，看 build 工具的倍數裡有多少來自語言。`,en:`On one machine, "Rust is faster" is broken into a dozen cases and each is measured on its own. The results range from Node being faster, through a tie, to Rust being 35 times faster. The last part compares three real tools, Babel, SWC and esbuild, to see how much of a build tool's speedup comes from the language.`},intro:{zh:`<p>十四張圖，分六組。有幾組的結論會互相衝突，要對照著看。例如 1a 的加總兩邊打平，可是 4a 一樣是手寫迴圈，Rust 卻快四倍。4b 裡 Rust 因為沒有分支所以比較快，到了 4c 把陣列改短，反而是 Node 比較快。</p><h3>一、平手，跟平手的原因</h3><table><tbody><tr><td>1a</td><td>同一個加總跑五十輪，誰比較快</td><td>平手，Node 9.78ms、Rust 9.65ms</td></tr><tr><td>1b</td><td>1a 為什麼平手</td><td>每一筆加法都要等上一筆算完。改成四個各自獨立的加總，Node 快 3.0 倍，Rust 快 4.3 倍</td></tr></tbody></table><h3>二、JIT warmup 與 deoptimization</h3><table><tbody><tr><td>2a</td><td>換成短函式、呼叫很多次，warmup 看得出來嗎</td><td>看得出來。前 200 次呼叫 Node 慢 67 倍，第 600 到 800 次呼叫之後剩約 1.5 倍</td></tr><tr><td>2b</td><td>1a 為什麼看不到 warmup</td><td>OSR（on-stack replacement）在那一次長呼叫的中途，就把函式換成優化版</td></tr><tr><td>2c</td><td>V8 猜錯型別時，那一批會慢幾倍</td><td>慢 6.1 倍，下一批就恢復</td></tr></tbody></table><p class="note">2b 和 2c 量的是 V8（Node 的 JavaScript 引擎）自己的機制。Rust 沒有這種機制，所以這兩張只有 Node。</p><h3>三、GC 的停頓</h3><table><tbody><tr><td>3</td><td>GC（garbage collection）會不會讓每一輪的時間不穩</td><td>會。Node 的中位數快 16%，但最慢的 1% 是 Rust 的 1.8 倍</td></tr></tbody></table><h3>四、抽象與分支</h3><table><tbody><tr><td>4a</td><td>用 map／filter 串接，會不會比手寫迴圈慢</td><td>Rust 不會，Node 慢九倍。兩邊都用手寫迴圈的話，Rust 快四倍</td></tr><tr><td>4b</td><td>4a 手寫迴圈那將近四倍，原因是什麼</td><td>branch prediction 猜錯讓 Node 慢了 1.7 倍，扣掉之後 Node 還是慢 2.3 倍</td></tr><tr><td>4c</td><td>陣列短的時候，4b 的結論還成立嗎</td><td>不成立，陣列短的時候反而 Node 快</td></tr></tbody></table><p class="note">4b 和 4c 的結論相反，原因是陣列長度不同。CPU 遇到分支時，會照前幾次的走向先猜一條路。陣列短的話，整串走向都記得下來，幾乎每次都猜對；陣列長到記不下來，就有一半會猜錯。4c 量出的交叉點在四千到一萬六千筆之間，四千筆以下 Node 快，一萬六千筆以上 Rust 快。</p><h3>五、build 工具會遇到的情況</h3><table><tbody><tr><td>5a</td><td>只跑一次就結束的工作，Rust 快幾倍</td><td>2.7 到 3.7 倍（兩組各量 40 次）</td></tr><tr><td>5b</td><td>同一個工作在一個 process 裡跑三百次</td><td>縮到 1.48 倍</td></tr><tr><td>5c</td><td>換成 bundler 那種走訪 AST 的工作</td><td>2.68 倍，沒有比 5a 大</td></tr></tbody></table><h3>六、多核心與實際在用的工具</h3><table><tbody><tr><td>6a</td><td>開到八個執行緒，兩邊各快幾倍</td><td>Node 快 6.2 倍，Rust 快 7.6 倍，兩邊都能用多核心</td></tr><tr><td>6b</td><td>SWC 宣稱比 Babel 快 20 倍，有多少是 Rust 的功勞</td><td>語言本身只差約 2.7 倍。Go 寫的 esbuild 也比 Babel 快五倍以上</td></tr></tbody></table><p class="note">1a 到 5c 都是單執行緒對單執行緒，只比語言。6a 另外加上多執行緒，6b 另外換成兩個實際在用的工具，每一組只多一個變因。同一份演算法用單執行緒跑，Rust 大約比 Node 快 3 倍；最像 bundler 的 5c 是 2.7 倍。開到八個執行緒以後，Node 比自己的單執行緒快 6 倍，Rust 快 7.5 倍。所以在 6a 走訪 AST 的那組裡，Rust 領先的倍數從單執行緒的 2.8 倍拉開到八執行緒的 3.4 倍。SWC 是 Rust 寫的，Babel 是 JavaScript 寫的。編譯成 ES2019 時，SWC 比 Babel 快 6.8 倍；如果要看寫法的差別，就得先除以語言本身的 2.7 倍。除完還剩約 2.5 倍，這部分大概來自兩個程式的寫法不同。</p>`,en:`<p>Fourteen charts in six groups. Some groups contradict each other and need to be read side by side. In 1a the sum is a tie, yet in 4a, also a hand written loop, Rust is four times faster. In 4b Rust is faster because it has no branch, but in 4c, with a short array, Node is faster.</p><h3>1. A tie, and the reason for it</h3><table><tbody><tr><td>1a</td><td>The same sum, fifty rounds. Which is faster</td><td>A tie, Node 9.78ms, Rust 9.65ms</td></tr><tr><td>1b</td><td>Why 1a is a tie</td><td>Each addition waits for the previous one to finish. With four independent sums instead, Node gets 3.0 times faster and Rust 4.3 times faster</td></tr></tbody></table><h3>2. JIT warmup and deoptimization</h3><table><tbody><tr><td>2a</td><td>With a short function called many times, can the warmup be seen</td><td>Yes. For the first 200 calls Node is 67 times slower; after call 600 to 800 it is about 1.5 times</td></tr><tr><td>2b</td><td>Why 1a shows no warmup</td><td>OSR (on-stack replacement) swaps the function for the optimized version partway through that one long call</td></tr><tr><td>2c</td><td>When V8 guesses a type wrong, how much slower is that batch</td><td>6.1 times slower, and the next batch recovers</td></tr></tbody></table><p class="note">2b and 2c measure V8's own mechanisms (V8 is Node's JavaScript engine). Rust has no such mechanism, so these two charts show Node only.</p><h3>3. GC pauses</h3><table><tbody><tr><td>3</td><td>Does GC (garbage collection) make the time per round unstable</td><td>Yes. Node's median is 16% faster, but its slowest 1% is 1.8 times Rust's</td></tr></tbody></table><h3>4. Abstraction and branches</h3><table><tbody><tr><td>4a</td><td>Is a map / filter chain slower than a hand written loop</td><td>Not in Rust; in Node it is nine times slower. With hand written loops on both sides, Rust is four times faster</td></tr><tr><td>4b</td><td>What causes the nearly four times in the 4a hand written loop</td><td>Wrong branch predictions make Node 1.7 times slower; without them Node is still 2.3 times slower</td></tr><tr><td>4c</td><td>Does the 4b conclusion hold for short arrays</td><td>No. With short arrays Node is faster</td></tr></tbody></table><p class="note">4b and 4c reach opposite conclusions because the array length differs. At a branch, the CPU guesses a path based on which way it went the last few times. With a short array the whole sequence of outcomes fits in its record, so it guesses right almost every time; with an array too long to record, about half the guesses are wrong. 4c puts the crossover between four thousand and sixteen thousand items: below four thousand Node is faster, above sixteen thousand Rust is faster.</p><h3>5. The cases a build tool runs into</h3><table><tbody><tr><td>5a</td><td>For a job that runs once and exits, how many times faster is Rust</td><td>2.7 to 3.7 times (two sets of 40 runs)</td></tr><tr><td>5b</td><td>The same job three hundred times in one process</td><td>Shrinks to 1.48 times</td></tr><tr><td>5c</td><td>Bundler style work that walks an AST</td><td>2.68 times, no larger than 5a</td></tr></tbody></table><h3>6. Multiple cores and tools in real use</h3><table><tbody><tr><td>6a</td><td>With eight threads, how much faster does each side get</td><td>Node 6.2 times, Rust 7.6 times; both can use multiple cores</td></tr><tr><td>6b</td><td>SWC claims to be 20 times faster than Babel. How much of that is Rust</td><td>The language alone is about 2.7 times. esbuild, written in Go, is also more than five times faster than Babel</td></tr></tbody></table><p class="note">1a to 5c are all single thread against single thread, comparing only the language. 6a adds multiple threads, and 6b swaps in two tools in real use; each group changes one variable. Running the same algorithm on one thread, Rust is about 3 times faster than Node (2.7 times in 5c). With eight threads, Node gets 6 times faster than its own single thread and Rust 7.5 times, so on the 6a workload the gap widens from 2.8 times on one thread to 3.4 times on eight. SWC is written in Rust and Babel in JavaScript. Compiling to ES2019, SWC is 6.8 times faster than Babel; to see how much comes from how they are written, divide by the language's 2.7 times first. About 2.5 times is left, and that part most likely comes from the two programs being written differently.</p>`},charts:[{num:`1a`,subtitle:{zh:`同一個加總跑五十輪：兩邊平手`,en:`The same sum, fifty rounds: a tie`},description:{zh:`一千萬個 f64 相加，跑五十輪，取穩定之後的中位數。這是 V8 最擅長的情況：型別從頭到尾只有一種，陣列在記憶體裡是連續的，而且這段跑得夠多次。`,en:`Add up ten million f64 values, fifty rounds, take the median after it stabilizes. This is the case V8 handles best: one type from start to end, the array is contiguous in memory, and this code runs enough times.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
// Data: ten million random numbers in 0~1
const data = new Array(10_000_000);
for (let i = 0; i < data.length; i++) data[i] = Math.random();
// data = [0.4231, 0.9917, 0.0038, 0.5561, ...]  \u2190 one-dimensional array, all f64

function sumArray(arr) {
  let s = 0;
  for (let i = 0; i < arr.length; i++) s += arr[i];
  return s;
}

sumArray(data);   // \u2190 this one call is what gets timed, fifty rounds, take the median
\`\`\`

\`\`\`rust
// The same ten million f64, as Vec<f64>
let data: Vec<f64> = (0..10_000_000).map(|_| rng()).collect();

fn sum_array(data: &[f64]) -> f64 {
    let mut s = 0.0;
    for &x in data { s += x; }
    s
}

sum_array(&data);   // fifty rounds as well
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`1000 萬筆 f64 加總`,en:`Sum of 10M f64`}],datasets:[e(`Node`,[9.776],t.node),e(`Rust`,[9.647],t.rust)]},options:s(`ms`)},conclusion:{zh:`Node 9.78ms，Rust 9.65ms，只差 1.3%。這種加總每一步都要等上一步算完，所以兩邊都停在一次加法要等的時間上，誰產生的 machine code 比較好，都改變不了結果（1b 會分開驗證這件事）。至少在這種迴圈上，「JS 要經過引擎所以慢」不成立，因為 V8 的最佳化編譯器 TurboFan 最後產生的也是 machine code。`,en:`Node 9.78ms, Rust 9.65ms, only 1.3% apart. In this sum every step waits for the previous one to finish, so both sides run at the speed of one addition's wait, and better machine code on either side cannot change the result (1b tests this separately). At least for this kind of loop, "JS goes through an engine, so it is slow" does not hold, because V8's optimizing compiler TurboFan also produces machine code in the end.`}},{num:`1b`,subtitle:{zh:`平手是因為每筆加法都要等上一筆，改成四個獨立的加總後，Node 快 3.0 倍，Rust 快 4.3 倍`,en:`The tie comes from each addition waiting for the last: with four independent sums, Node gets 3.0 times faster and Rust 4.3 times faster`},description:{zh:`1a 的平手，是不是因為每一筆加法都要等上一筆算完？這組拿兩種寫法來對照。左邊那根跟 1a 是同一個加總迴圈，資料換成一千筆，重複加十萬輪。s 在輪跟輪之間不歸零，第二輪接著第一輪的結果往下加（s = s + 這一筆）。一千筆乘十萬輪是一億次加法，從頭到尾都要一筆加完才能加下一筆。要是每輪把 s 歸零，下一輪的第一筆就不用等上一輪的最後一筆。這時 CPU 會在上一輪還沒加完的時候，先開始加下一輪的前幾筆，兩輪的加法有一段重疊。所以平均到每一筆，量到的時間會比一次加法還短。舊版每輪都把 s 歸零，Rust 量到 0.81 ns，比 1a 量到的一次加法 0.96 ns 還快，下面的修正紀錄寫了怎麼改。右邊改寫成四個各自獨立的加總，四個彼此不用等，CPU 可以同時算。資料跟語言都沒變，只改了加法的順序，所以右邊要是變快，就表示 1a 卡在這個順序上。`,en:`Is 1a a tie because each addition has to wait for the previous one? This group compares two ways of writing the sum. The left bar is the same sum loop as 1a, with the data cut to one thousand items and summed over one hundred thousand rounds. s is not reset between rounds; the second round continues from the result of the first (s = s + this item), so across all one hundred million additions, each one must finish before the next starts. If s were reset every round, the first addition of the next round would not wait for the last addition of the previous one. The CPU would then start the first few additions of the next round before the previous round finished, so the two rounds overlap for a while, and the time per element comes out shorter than one addition. The old version reset s every round, and Rust measured 0.81 ns, faster than the 0.96 ns 1a measured for one addition. The correction note below says what changed. The right bar rewrites it as four independent sums that do not wait for each other, so the CPU can run them at the same time. Data and language stay the same and only the order of the additions changes, so if the right side gets faster, 1a was held back by that order.`},lang:`raw`,codeLabel:`JS`,sql:`\`\`\`js
// Left bar: the 1a sum, every step uses the previous s, so one after another only
// s is set to 0 once, outside the 100k rounds, and never reset: 1000 items x 100k rounds = one chain of 100M adds
let s = 0;
for (let i = 0; i < data.length; i++) s += data[i];

// Right bar: four independent sums, unrelated to each other, the CPU can run them at the same time
let a = 0, b = 0, c = 0, d = 0;
for (let i = 0; i < data.length; i += 4) {
  a += data[i]; b += data[i+1]; c += data[i+2]; d += data[i+3];
}
const total = a + b + c + d;
\`\`\``,chart:{type:`bar`,data:{labels:[`sequential`,{zh:`四個各自獨立`,en:`4 independent`}],datasets:[e(`Node`,[.97,.33],t.node),e(`Rust`,[.97,.23],t.rust)]},options:s({zh:` ns/元素`,en:` ns/elem`})},conclusion:{zh:`<p>每邊跑五個 process，圖上是五個中位數再取中位數。左邊那根，Node 和 Rust 都是每個元素 0.97 ns，跟 1a 一樣，大約 3 個 cycle，也就是一次浮點加法從開始到算出結果的時間。每一次 s += data[i] 都要等上一次的 s 算好，所以兩邊都停在這個速度上。慢在等上一次加法的結果，跟編譯器產生的 machine code 好不好無關。</p><p>改成四個各自獨立的加總之後，四個加法可以同時算，Node 降到 0.33 ns，Rust 降到 0.23 ns，分別快 3.0 倍跟 4.3 倍。資料跟語言都沒變，只改了加法的順序，所以 1a 的平手來自這個一筆等一筆的順序。</p><p class="caveat">這組只用一千筆資料（1a 是一千萬筆）。一千筆 f64 是 8KB，整個放得進 CPU 的 cache，不用等記憶體，結果還是平手，所以 1a 的平手不是因為兩邊都在等讀資料。</p><p class="caveat">浮點加法換了順序，最後的捨入就會不一樣。例如 (0.1 + 0.2) + 0.3 是 0.6000000000000001，0.1 + (0.2 + 0.3) 是 0.6。換順序等於改了答案，所以編譯器不會自動拆成四個，這個寫法得自己手寫。</p><p class="caveat">修正紀錄：舊版每輪都把 s 歸零，只跑一個 process，左邊那根量到 Node 0.92、Rust 0.81 ns。1a 量到的一次加法是 0.96 到 0.97 ns，Rust 的 0.81 比一次加法還快，表示前後兩輪的加法有重疊，量到的不是單純一次加法的時間。2026-10-24 改成 s 跨輪接著加，下一輪的第一筆一定要等上一輪的最後一筆，重疊就沒了。改完之後每邊重跑五個 process，兩邊都是 0.97 ns。每一次都是先跑 Node，跑完緊接著跑 Rust，拿同一次的 Node 時間除以 Rust 時間，五次裡 Node 慢 0.6% 到 6.4%，中位數 0.7%。歸零的版本留在 f.rs、f.js 裡，這次也重跑了：Node 0.94、Rust 0.83 ns。</p>`,en:`<p>Each side ran five processes; the chart shows the median of the five medians. On the left bar Node and Rust are both at 0.97 ns per element, the same as 1a, about 3 cycles, which is how long one floating point addition takes from start to result. Every s += data[i] waits for the previous s, so both sides run at that speed. The time goes to waiting for the previous addition, and better machine code does not change that.</p><p>With four independent sums the additions can run at the same time, and Node drops to 0.33 ns and Rust to 0.23 ns, 3.0 and 4.3 times faster. Data and language stay the same and only the order of the additions changes, so the tie in 1a comes from that one-waits-for-the-last order.</p><p class="caveat">This group uses only one thousand items (1a uses ten million). One thousand f64 values are 8KB, which fits entirely in the CPU cache with no waiting on memory, and it is still a tie, so the tie in 1a is not because both sides wait on memory reads.</p><p class="caveat">Changing the order of floating point additions changes the final rounding. For example, (0.1 + 0.2) + 0.3 is 0.6000000000000001, while 0.1 + (0.2 + 0.3) is 0.6. A different order means a different answer, so the compiler does not split the sum into four on its own; it has to be written by hand.</p><p class="caveat">Correction note: the old version reset s every round and ran one process, and the left bar measured Node 0.92 and Rust 0.81 ns. 1a measured one addition at 0.96 to 0.97 ns. Rust's 0.81 is faster than one addition, which means additions from two rounds overlapped, so the number was not the time of one addition. On 2026-10-24 s was changed to carry over between rounds, so the first addition of a round has to wait for the last addition of the previous round, and the overlap is gone. After the change each side ran five processes, and both are at 0.97 ns. Each time Node ran first and Rust right after it; dividing that run's Node time by its Rust time, Node is 0.6% to 6.4% slower over the five runs, median 0.7%. The resetting version stays in f.rs and f.js and was rerun too: Node 0.94, Rust 0.83 ns.</p>`}},{num:`2a`,subtitle:{zh:`Warmup：Node 前 200 次呼叫比 Rust 慢 67 倍，第 600 到 800 次之間降到只慢 1.5 倍`,en:`Warmup: for the first 200 calls Node is 67 times slower than Rust; between calls 600 and 800 it drops to only 1.5 times slower`},description:{zh:`warmup 是「同一個函式被呼叫很多次之後，V8 把它優化、變快」。要看到它，就得呼叫很多次、看每次的成本怎麼往下掉。1a 只呼叫一次（那一次裡面跑一千萬圈），變快的過程整個發生在那一次裡面，攤進了那一次的平均，所以看不到（2b 把這個「藏起來」的機制查出來）。這一組改用小函式（加總一百筆）呼叫上萬次，每 200 次量一段時間再除以 200，看每次呼叫的成本怎麼隨呼叫數往下掉。`,en:`Warmup means "after the same function is called many times, V8 optimizes it and it gets faster". To see it, the function must be called many times, and the cost per call watched as it drops. 1a calls only once (that one call runs ten million iterations), so the whole process of getting faster happens inside that call and is spread into its average, which hides it (2b tracks down the mechanism that "hides" it). This group switches to a small function (sum of one hundred items) called tens of thousands of times. Every 200 calls are timed as one block and divided by 200, to see how the cost per call drops as the call count grows.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
// Small function, loop of only 100 iterations (does not trigger OSR), called tens of thousands of times
// Time every 200 calls as one block and divide by 200 (timing one at a time drowns in the timer cost)
for (let b = 0; b < 60; b++) {
  const start = process.hrtime.bigint();
  for (let c = 0; c < 200; c++) sink += sumSmall(data);
  console.log(Number(process.hrtime.bigint() - start) / 200);  // ns/call
}
\`\`\`

\`\`\`rust
// Rust has no JIT, the cost per call is flat from the first batch
for _ in 0..60 {
    let start = Instant::now();
    for _ in 0..200 { sink += sum_small(black_box(&data)); }
    // elapsed / 200 = ns/call
}
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`前 200 次`,en:`First 200`},{zh:`到 400 次`,en:`To 400`},{zh:`到 600 次`,en:`To 600`},{zh:`到 800 次`,en:`To 800`},{zh:`之後穩定`,en:`Stable after`}],datasets:[e(`Node`,[3892,2027,198,85,81.5],t.node),e(`Rust`,[58,56,56,57,55],t.rust)]},options:s({zh:` ns/次`,en:` ns/call`})},conclusion:{zh:`<p>每 200 次呼叫算一批，「到 600 次」就是第 401 到 600 次那一批。兩邊各跑十次，圖上的每一根長條，都是把十次執行裡同一批的數字取中位數。Node 前 200 次呼叫平均每次 3892 奈秒，比 Rust 的 58 慢 67 倍。第 201 到 400 次那一批降為 2027，到第 600 或 800 次就不再往下掉。</p><p>之後 Node 停在 81.5 奈秒左右，Rust 是 55.0 奈秒，差距從 67 倍縮到約 1.5 倍。十次執行降下來的批次不一樣，五次在「到 600 次」那一批，五次在「到 800 次」那一批，因為 V8 什麼時候從直譯器換成優化過的 machine code，每次都不一樣。所以在「到 600 次」那一批，已經降下來的五次是 81 到 90 奈秒，還沒降的五次是 306 到 1578 奈秒。十個數排好之後，第 5 個是 90.2，第 6 個是 306.5，中位數取這兩個的平均，也就是 198。這根長條不是哪一次執行真的跑出來的數字。</p><p>Node 在這裡變快，是因為 V8 的 JIT（just-in-time 編譯）把函式換成編譯過的 machine code，但這組沒有單獨測量它換到 V8 四層裡的哪一層。Rust 沒有 JIT，所以從第一批 200 次開始就是平的。</p><p class="caveat">V8 執行一個函式的方式有四層，函式被呼叫越多次，就換到越高的一層。第一層是 <b>Ignition</b> 直譯器，啟動快、跑得慢，一開始都用它。第二層 <b>Sparkplug</b> 很快編譯出一份沒有優化的 machine code。第三層 <b>Maglev</b> 做中等程度的優化，大約在 400 次呼叫時接手。第四層 <b>TurboFan</b> 優化得最多，大約在 3000 次時接手，編譯最久，跑得也最快。上面那個下降發生在頭幾百次，比 3000 次早，所以主要是前三層的效果。</p><p class="caveat">為什麼要一次測量 200 次、再除以 200，而不是一次一次測量呢？因為讀一次時鐘本身就要花幾十奈秒，跟穩定之後一次呼叫的 55 到 80 奈秒差不多，一次一次量的話，量到的時間有一大半是讀時鐘花的。把 200 次放在一起，只在頭尾各讀一次時鐘，200 次呼叫穩定之後大約是 11000 到 16000 奈秒，讀時鐘那幾十奈秒就不到 1%。</p>`,en:`<p>Every 200 calls form one batch, so "To 600" is the batch of calls 401 to 600. Each side runs ten times, and each bar is the median of the ten runs for that batch. For the first 200 calls, Node averages 3892 nanoseconds per call, 67 times slower than Rust at 58. The batch of calls 201 to 400 comes down to 2027, and by call 600 or 800 it stops dropping.</p><p>After that, Node stays at about 81.5 nanoseconds and Rust at 55.0, so the gap shrinks from 67 times to about 1.5 times. The batch where Node drops differs between runs: five of the ten in the "To 600" batch, the other five in "To 800", because the moment V8 moves from the interpreter to optimized machine code differs from run to run. So in the "To 600" batch, the five runs that had already dropped are at 81 to 90 nanoseconds and the five that had not are at 306 to 1578. Sorted, the 5th value is 90.2 and the 6th is 306.5, and the median is their average, 198. No single run actually measured that number.</p><p>Node gets faster here because V8's JIT (just-in-time compiler) swaps the function for compiled machine code. Rust has no JIT, so it is flat from the first batch of 200 calls.</p><p class="caveat">V8 has four tiers for running a function, and the more times a function is called, the higher the tier it moves to. The first is the <b>Ignition</b> interpreter, which starts fast, runs slow, and is used at the beginning. The second, <b>Sparkplug</b>, quickly compiles an unoptimized copy of machine code. The third, <b>Maglev</b>, optimizes moderately and takes over at about 400 calls. The fourth, <b>TurboFan</b>, optimizes the most and takes over at about 3000 calls; it takes longest to compile and runs fastest. The drop above happens in the first few hundred calls, earlier than 3000, so it comes mainly from the first three tiers.</p><p class="caveat">Why time 200 calls as one block and divide, instead of one call at a time? Reading the clock once takes tens of nanoseconds, close to the 55 to 80 nanoseconds of one settled call, so timing one call at a time would mostly measure the clock. With 200 calls together and the clock read once at each end, the 200 settled calls take about 11000 to 16000 nanoseconds, and the tens of nanoseconds for the clock are under 1%.</p>`}},{num:`2b`,subtitle:{zh:`1a 為什麼看不到 warmup：OSR 在那一次長呼叫的中途就換成優化版`,en:`Why 1a shows no warmup: OSR swaps in the optimized version partway through that one long call`},description:{zh:`<strong>這組跟 2c 一樣，量的是 V8（Node 的 JavaScript 引擎）自己的機制。Rust 沒有這種機制，所以圖上兩條 bar 都是 Node。</strong><br><br>2a 量得出 warmup，1a 卻看不出來，1a 第一輪跟穩定之後的時間幾乎一樣。為什麼呢？<br><br>OSR（on-stack replacement）是 V8 的一個機制。一個函式只被呼叫一次、但裡面的迴圈要跑很久的時候，V8 不等呼叫結束，迴圈跑到一半就把這個函式換成優化過的版本。沒有 OSR 的話，要等到下一次呼叫才會換。<br><br>這組用 1a 的加總函式，分別處理三種長度的陣列（10 萬、100 萬、1000 萬筆），每種長度再分成 OSR 開跟 OSR 關。每種組合開 15 個新的 process，每個 process 呼叫 41 次，算一次倍率，最後取 15 個倍率的中位數。<p class="note">表裡每個數字都是「第 1 次呼叫的時間 ÷ 第 2 到 41 次呼叫的中位數」，1 倍表示第 1 次跟之後一樣快。不管 OSR 開或關，到第 2 次呼叫時函式都已經換成優化版，所以拿後面 40 次當基準。</p><table class="grid"><thead><tr><th>陣列長度</th><th>OSR 開（預設）</th><th>OSR 關（對照）</th></tr></thead><tbody><tr><td>10 萬圈</td><td>8.9 倍</td><td>16.5 倍</td></tr><tr><td>100 萬圈</td><td>1.8 倍</td><td>13.1 倍</td></tr><tr><td>1000 萬圈（1a 跑的就是這個長度）</td><td class="here">1.1 倍</td><td>13.3 倍</td></tr></tbody></table>`,en:`<strong>Like 2c, this group measures a mechanism of V8 itself (V8 is Node's JavaScript engine). Rust has no such mechanism, so both bars in the chart are Node.</strong><br><br>2a shows a warmup, but 1a does not: in 1a the first round takes almost the same time as after it stabilizes. Why?<br><br>OSR (on-stack replacement) is a V8 mechanism. When a function is called only once but its loop runs for a long time, V8 does not wait for the call to end; partway through the loop it swaps in an optimized version. Without OSR, the swap waits until the next call.<br><br>This group runs the 1a sum at three array lengths (100K, 1M, 10M items), each with OSR on and OSR off. Each combination starts 15 fresh processes; each process makes 41 calls and computes one ratio, and the median of the 15 ratios is reported.<p class="note">Every number in the table is "time of call 1 \xF7 median of calls 2 to 41", so 1x means call 1 is as fast as the rest. With OSR on or off, the function has been swapped for the optimized version by call 2, which is why calls 2 to 41 are the baseline.</p><table class="grid"><thead><tr><th>Array length</th><th>OSR on (default)</th><th>OSR off (control)</th></tr></thead><tbody><tr><td>100K iterations</td><td>8.9x</td><td>16.5x</td></tr><tr><td>1M iterations</td><td>1.8x</td><td>13.1x</td></tr><tr><td>10M iterations (the length 1a runs)</td><td class="here">1.1x</td><td>13.3x</td></tr></tbody></table>`},lang:`raw`,codeLabel:{zh:`指令`,en:`Commands`},sql:`\`\`\`bash
# Each cell starts 15 fresh processes, each measures the "first call / stable" ratio once, then take the median
# (repeating inside one process is warmed by the previous run, so the true first call cannot be measured)
for i in $(seq 15); do node a3-oneshot.js 10000000; done   # OSR on
for i in $(seq 15); do node --no-use-osr a3-oneshot.js 10000000; done
# All six cells: bash run-all.sh a3, output in results/a3.csv
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`10 萬圈`,en:`100K iters`},{zh:`100 萬圈`,en:`1M iters`},{zh:`1000 萬圈（1a 的長度）`,en:`10M iters (1a length)`}],datasets:[e({zh:`OSR 開（預設）`,en:`OSR on (default)`},[8.86,1.76,1.13],t.nodeAlt),e({zh:`OSR 關（對照）`,en:`OSR off (control)`},[16.45,13.09,13.25],t.node)]},options:s({zh:` 倍`,en:`x`})},conclusion:{zh:`<p>1a 跑的組合是 1000 萬圈、OSR 開，第一次呼叫只比之後慢 <b>1.13 倍</b>，所以 1a 的第一輪跟穩定之後幾乎一樣。</p><p>OSR 開的那一排，迴圈越長，倍率越小（8.9 → 1.8 → 1.1）。第一次呼叫會先用慢的版本跑一段，等 V8 把優化版編譯好、換上去，剩下的圈數才變快。慢的那一段大約幾萬圈，長度差不多固定，用三種長度的倍率可以回推出來。在 1000 萬圈裡，這幾萬圈不到 1%，所以第一次呼叫幾乎全程都在跑優化版。</p><p>OSR 關的那一排是對照，不讓 V8 中途換版本，三種長度都慢 13 到 16 倍。沒有 OSR 的話，第一次呼叫就是這麼慢。所以 1a 也有 warmup，只是 OSR 讓它只佔那一次長呼叫的一小段。要看到 warmup，得像 2a 那樣改用短迴圈、呼叫很多次。</p><p class="caveat">OSR 關的那一排，10 萬圈是 16.5 倍，比另外兩種長度的 13 倍左右高，原因沒有查。</p>`,en:`<p>1a runs 10M iterations with OSR on, and there the first call is only <b>1.13 times</b> slower than the rest, so the first round of 1a is almost the same as after it stabilizes.</p><p>In the OSR on column, the longer the loop, the smaller the ratio (8.9 → 1.8 → 1.1). The first call runs a stretch on the slow version until V8 finishes compiling the optimized version and swaps it in, and only the remaining iterations are fast. That slow stretch is about tens of thousands of iterations and roughly fixed in length, which can be worked back from the ratios at the three lengths. In 10M iterations it is under 1%, so the first call runs the optimized version for almost its whole length.</p><p>The OSR off column is the control, where V8 is not allowed to swap partway through, and all three lengths are 13 to 16 times slower. Without OSR, the first call really is this slow. So 1a does have a warmup; OSR just makes it a small part of that one long call. To see the warmup, use a short loop called many times, as in 2a.</p><p class="caveat">In the OSR off column, 100K iterations is 16.5 times, higher than the roughly 13 times at the other two lengths. The reason was not investigated.</p>`}},{num:`2c`,subtitle:{zh:`Deoptimization：混進字串的那一批慢 6 倍`,en:`Deoptimization: the batch with strings mixed in is 6 times slower`},description:{zh:`<strong>這組跟 2b 一樣，量的是 V8 自己的機制。Rust 沒有這種機制，所以兩條 bar 都是 Node。</strong>同一個 <code>add(a, b)</code> 用整數呼叫兩千萬次，每一百萬次算一批，一共二十批。其中一版在第十批開始前，先用字串呼叫一千次 <code>add("foo", "bar")</code>。<br><br>V8 會猜參數的型別。一直收到整數的話，它會在執行期編譯出一份 machine code，這份 code 假設參數都是整數，跳過型別檢查，所以做加法時比較快。之後要是收到的不是整數，這份 machine code 就不能用了，V8 會丟掉它，退回沒有優化的版本執行，這叫 deoptimization（deopt）。`,en:`<strong>Like 2b, this group measures a mechanism of V8 itself. Rust has no such mechanism, so both bars are Node.</strong> The same <code>add(a, b)</code> is called twenty million times with integers, one million calls per batch, twenty batches in all. One version calls <code>add("foo", "bar")</code> one thousand times with strings just before batch ten starts.<br><br>V8 guesses the types of the arguments. If it keeps receiving integers, it compiles at run time a copy of machine code that assumes the arguments are integers and skips the type check, so the addition runs faster. If a non-integer arrives later, that machine code can no longer be used; V8 throws it away and falls back to the unoptimized version. This is called deoptimization (deopt).`},lang:`raw`,codeLabel:`JS / V8 trace`,sql:`\`\`\`js
function add(a, b) { return a + b; }

// Pollute the type before batch 10
if (mode === "polluted" && batch === 10) {
  for (let i = 0; i < 1000; i++) strSink = add("foo", "bar");
}
for (let i = 0; i < 1_000_000; i++) acc += add(i, 1);
\`\`\`

\`\`\`text
$ node --trace-deopt b.js polluted
[bailout (kind: deopt-eager, reason: not a Smi): begin.
 deoptimizing <JSFunction add>, <Code TURBOFAN>, opt id 0, ...]
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`第 9 批`,en:`Batch 9`},{zh:`第 10 批`,en:`Batch 10`},{zh:`第 11 批`,en:`Batch 11`}],datasets:[e({zh:`型別乾淨`,en:`Clean types`},[.929,.987,.944],t.nodeAlt),e({zh:`混入字串`,en:`Strings mixed in`},[.93,6.024,.929],t.node)]},options:s(`ms`)},conclusion:{zh:`混進字串的那一批從 0.987ms 變成 6.024ms，慢了 6.1 倍，下一批就恢復了。<code>--trace-deopt</code> 印出的原因是 not a Smi，Smi 是 V8 內部表示小整數（small integer）的格式。<strong>Rust 這組沒有數字可以比</strong>，因為型別寫錯的話，Rust 在編譯時就會報錯，不會產生執行檔，所以執行時不會有「先猜型別、猜錯再退回慢的版本」這件事。`,en:`The batch with strings mixed in goes from 0.987ms to 6.024ms, 6.1 times slower, and the next batch recovers. The reason <code>--trace-deopt</code> prints is "not a Smi"; Smi is V8's internal format for a small integer. <strong>Rust has no number to compare in this group</strong>, because with a wrong type Rust reports an error at compile time and produces no executable, so at run time there is no "guess the type, fall back to the slow version when wrong".`}},{num:`3`,subtitle:{zh:`GC（garbage collection）：Node 的中位數比較快，但 p99 花的時間是 Rust 的 1.7 倍`,en:`GC (garbage collection): Node's median is faster, but its p99 takes 1.7 times as long as Rust's`},description:{zh:`一共兩百輪，每輪建立十萬個用完就丟的小物件。物件的樣子在下面的 code 裡，有 <code>{ id, name, value }</code> 三個欄位。<br><br>這裡不能只看平均。假設兩百輪裡有一百九十六輪都是 4ms，四輪因為 GC 停頓變成 12ms，平均只有 4.16ms，光看平均就找不到那四輪。<br><br>所以要把兩百輪的時間從快到慢排好，看三個位置。第一個是第 100 輪，叫 p50，也就是中位數，一半的輪次比它快。第二個是第 198 輪，叫 p99，只有最慢的 2 輪比它更慢，上面例子裡的 12ms 會落在這裡。第三個是最慢的那一輪。整組跑五次，圖上每個位置都是五次的中位數。`,en:`Two hundred rounds in all. Each round creates one hundred thousand small objects that are used once and discarded; the code below shows the object, with three fields <code>{ id, name, value }</code>.<br><br>The average alone is no use here. Suppose 196 of the 200 rounds take 4ms and four rounds take 12ms because of GC pauses: the average is only 4.16ms, and the average never finds those four rounds.<br><br>So sort the 200 round times from fast to slow and look at three positions. The first is round 100, called p50 or the median; half the rounds are faster. The second is round 198, called p99; only the 2 slowest rounds are slower, and the 12ms rounds in the example above land here. The third is the slowest round. The whole set runs five times, and each position in the chart is the median of the five.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
function oneRound() {
  const arr = new Array(100_000);
  for (let i = 0; i < 100_000; i++) {
    arr[i] = { id: i, name: "obj-" + i, value: i * 0.5 };
  }
  // ...used once and discarded, left to the GC
}
\`\`\`

\`\`\`rust
fn one_round(objs: usize) -> f64 {
    let arr: Vec<Obj> = (0..objs)
        .map(|i| Obj { id: i, name: format!("obj-{}", i), value: i as f64 * 0.5 })
        .collect();
    // ...freed when it leaves scope, each String asks the allocator once
}
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`中位數 p50`,en:`Median p50`},{zh:`最慢的 1% p99`,en:`Slowest 1% p99`},{zh:`最慢的那一輪`,en:`Slowest round`}],datasets:[e(`Node`,[4.34,10.34,11.37],t.node),e(`Rust`,[5.05,5.74,5.77],t.rust)]},options:s(`ms`)},conclusion:{zh:`<p>Node 的中位數是 4.34ms，比 Rust 的 5.05ms 快 16%。V8 的 generational GC 就是為這種大量用完就丟的物件設計的。新物件放進一塊連續的記憶體，配置時只要把指標往後移；回收時只搬走還活著的少數幾個，其餘整塊清掉。Rust 這邊，每個物件的字串都要向 allocator 要一次記憶體，用完再一個一個釋放。</p><p>但最慢的 1% 就反過來了。Node 的 p99 是 10.34ms，最慢那一輪 11.37ms；Rust 的 p99 是 5.74ms，最慢那一輪 5.77ms，跟中位數差不到 1ms。</p><p>另外開一個 process 跑 <code>--trace-gc</code>，200 輪裡 GC 一共停了 275 次，加起來 494ms，最長的一次 4.29ms。</p>`,en:`<p>Node's median is 4.34ms, 16% faster than Rust at 5.05ms. V8's generational GC is designed for exactly this kind of object, created in bulk and thrown away. New objects go into one contiguous block of memory, so allocating is just moving a pointer forward; collection moves only the few objects still alive and clears the rest of the block at once. On the Rust side, each object's string asks the allocator for memory once and is freed one by one after use.</p><p>The slowest 1% goes the other way. Node's p99 is 10.34ms and its slowest round 11.37ms; Rust's p99 is 5.74ms and its slowest round 5.77ms, less than 1ms above its median.</p><p>In a separate process run with <code>--trace-gc</code>, GC stopped 275 times over the 200 rounds, 494ms in total, the longest stop 4.29ms.</p>`}},{num:`4a`,subtitle:{zh:`Zero-cost abstraction：Rust 的 map／filter 串接跟手寫迴圈一樣快，Node 慢九倍`,en:`Zero-cost abstraction: a Rust map / filter chain is as fast as a hand written loop; in Node it is nine times slower`},description:{zh:`同一個計算寫兩種版本，一種手寫 for 迴圈，一種把 map、filter、reduce 串起來，資料都是一千萬筆。各先跑五輪 warmup，再測二十輪取中位數。`,en:`The same computation written two ways: one a hand-written for loop, one a chain of map, filter and reduce, both on ten million items. Each runs five warmup rounds first, then twenty measured rounds, taking the median.`},lang:`raw`,codeLabel:{zh:`JS / Rust / 組合語言`,en:`JS / Rust / assembly`},sql:`\`\`\`js
// Same data, ten million random numbers in 0~1: arr = [0.42, 0.99, 0.003, ...]
// Hand-written for
for (let i = 0; i < arr.length; i++) { const y = arr[i] * 2; if (y > 1) s += y; }
// Chained: map and filter each produce an intermediate array of ten million items
arr.map((x) => x * 2).filter((y) => y > 1).reduce((a, b) => a + b, 0);
\`\`\`

\`\`\`rust
// The same ten million f64
// Hand-written for
for &x in data { let y = x * 2.0; if y > 1.0 { s += y; } }
// Chained
data.iter().map(|x| x * 2.0).filter(|y| *y > 1.0).sum()
\`\`\`

The inner loops compiled from the two Rust functions are identical instruction by instruction, differing only in the form of the loop counter:

\`\`\`text
manual (LBB12_2)          chained (LBB13_2)
  ldr   d2, [x0], #8        ldr   d2, [x0], #8
  fadd  d2, d2, d2          fadd  d2, d2, d2
  fadd  d3, d0, d2          fadd  d3, d0, d2
  fcmp  d2, d1              fcmp  d2, d1
  fcsel d0, d3, d0, gt      fcsel d0, d3, d0, gt
  subs  x8, x8, #8          subs  x1, x1, #1
  b.ne  LBB12_2             b.ne  LBB13_2
\`\`\`

Line by line, what each one does against the source (d0 to d3 are registers holding floating point numbers, x0 and x8 hold the address and the count):

\`\`\`text
ldr   d2, [x0], #8     load one element from the array into d2, and move the address forward 8 bytes
fadd  d2, d2, d2       d2 plus itself, which is x * 2
fadd  d3, d0, d2       compute the "after adding" result first, into d3 (not yet decided whether to use it)
fcmp  d2, d1           compare d2 with d1 (which is 1.0)
fcsel d0, d3, d0, gt   if the compare said greater, d0 becomes d3, otherwise d0 stays as it is
subs  x8, x8, #8       counter minus 8, meaning one element (8 bytes) less remaining
b.ne  LBB12_2          not at the end yet, jump back to the loop start
\`\`\`

The full name of fcsel is floating-point conditional select. The source says \`if y > 1.0 { s += y }\`, and intuition expects it to compile to "jump to the addition only when the condition holds", but LLVM does not do that. It computes the result of the addition first into d3, then uses fcsel to pick d3 or the original d0. There is no jump anywhere, so the CPU does not need to predict which way to go, and no matter how random the data is it never guesses wrong. How large the gap is, 4b measures for real.`,chart:{type:`bar`,data:{labels:[{zh:`手寫 for 迴圈`,en:`Hand-written for loop`},`map + filter + reduce`],datasets:[e(`Node`,[61.761,577.69],t.node),e(`Rust`,[16.385,16.084],t.rust)]},options:s(`ms`)},conclusion:{zh:`<p>Rust 兩版只差 0.4%，在誤差範圍內，map／filter／reduce 那版甚至還快一點。下面 code 列出兩版內迴圈各七條指令，只有倒數第二條的迴圈計數器不同。手寫版的計數器以 byte 計，每圈減 8，因為一個 f64 是 8 bytes；串接版以元素計，每圈減 1。兩版每圈都處理一個元素。</p><p>Node 的 map／filter／reduce 那版慢了九倍，因為 map 先建立一個一千萬筆的新陣列，filter 再建立一個。</p>`,en:`<p>The two Rust versions differ by only 0.4%, within noise, and the map / filter / reduce version is even slightly faster. The code below lists the seven instructions of each inner loop. Only the second to last, the loop counter, differs. The hand written version counts in bytes and subtracts 8 per iteration, since one f64 is 8 bytes; the chained version counts elements and subtracts 1. Both handle one element per iteration.</p><p>The Node map / filter / reduce version is nine times slower, because map first builds a new array of ten million items and filter then builds another.</p>`}},{num:`4b`,subtitle:{zh:`Branch prediction：猜錯讓 Node 的手寫迴圈慢了 1.72 倍`,en:`Branch prediction: wrong guesses make the Node hand written loop 1.72 times slower`},description:{zh:`4a 的手寫迴圈，Node 要 62ms，Rust 要 16.4ms，差將近四倍。但 1a 的加總兩邊平手，所以這四倍不是加法本身造成的。<br><br>Rust 的 assembly 裡有一條 <code>fcsel</code>（floating-point conditional select）。它把加了跟沒加的兩個結果都先算出來，再依照條件挑一個，整段沒有跳躍指令，所以 CPU 不用猜接下來要走哪一條路。<br><br>V8 的編譯器 TurboFan 也會把這段編譯成 machine code，只是編譯發生在程式跑起來之後。不過 TurboFan 沒有用 <code>fcsel</code>，而是留下一條會跳躍的分支指令。CPU 為了不停下來等比較結果，會先猜一條路往下執行，猜錯就把那條路上做過的丟掉，回到分支重來。這個 if 大約一半的資料會進去，而且哪一筆會進去是隨機的，所以 CPU 大約有一半會猜錯。<br><br>驗證的做法是把條件換成幾乎永遠成立，其他都不動。如果 branch prediction 猜錯是原因之一，Node 會變快，Rust 不會變。`,en:`In the 4a hand written loop, Node takes 62ms and Rust 16.4ms, a gap of nearly four times. But the sum in 1a is a tie, so the four times does not come from the addition itself.<br><br>The Rust assembly has one <code>fcsel</code> (floating-point conditional select). It computes both results, with and without the addition, then picks one by the condition. There is no jump in the whole block, so the CPU has nothing to guess about which path comes next.<br><br>V8's compiler TurboFan also compiles this block to machine code, only the compile happens after the program starts running. But TurboFan does not use <code>fcsel</code>; it leaves a branch instruction that jumps. To avoid stopping and waiting for the comparison, the CPU guesses a path and keeps executing; on a wrong guess it throws away what it did on that path and goes back to the branch. About half the data enters this if, and which items enter is random, so the CPU guesses wrong about half the time.<br><br>To verify, change the condition to one that almost always holds and leave everything else alone. If wrong branch predictions are part of the cause, Node gets faster and Rust does not change.`},lang:`raw`,codeLabel:`JS / Rust`,sql:"```js\n// Condition holds half the time, branch prediction keeps guessing wrong\nif (y > 1) s += y;\n// Condition almost always true, easy branch to guess\nif (y > -1) s += y;\n```\n\n```rust\n// Both versions compile to fcsel, no branch, so predictability does not matter\nif y > 1.0 { s += y; }\nif y > -1.0 { s += y; }\n```",chart:{type:`bar`,data:{labels:[{zh:`一半進 if`,en:`Half enter if`},{zh:`幾乎都進 if`,en:`Almost all enter if`}],datasets:[e(`Node`,[62.633,36.353],t.node),e(`Rust`,[15.693,15.568],t.rust)]},options:s(`ms`)},conclusion:{zh:`<p>Node 從 62.633ms 變成 36.353ms，快了 1.72 倍。Rust 是 15.693 對 15.568ms，幾乎沒變，所以這 1.72 倍是分支猜錯造成的。分支難猜的時候 Node 比 Rust 慢 3.99 倍，扣掉分支之後還差 3.99 ÷ 1.72 = 2.32 倍。</p><p>Rust 的 assembly 裡一條 SIMD 指令都沒有，所以這 2.32 倍跟向量化無關。</p><p class="caveat">這裡的資料要同時符合兩個條件，CPU 才會一直猜錯。第一，資料是隨機的。第二，陣列長到 branch predictor 記錄不完，這裡是一千萬筆。陣列短的話，反而是 Node 比較快，4c 量的就是陣列長度的影響。</p>`,en:`<p>Node goes from 62.633ms to 36.353ms, 1.72 times faster. Rust is 15.693 against 15.568ms, almost no change, so the 1.72 times comes from wrong branch guesses. With the hard to guess branch Node is 3.99 times slower than Rust; without the branch cost, the gap is still 3.99 ÷ 1.72 = 2.32 times.</p><p>There is not a single SIMD instruction in the Rust assembly, so this 2.32 times has nothing to do with vectorization.</p><p class="caveat">The CPU keeps guessing wrong only when the data meets two conditions at once. First, the data is random. Second, the array is too long for the branch predictor to record, ten million items here. With a short array Node becomes the faster one, as 4c shows.</p>`}},{num:`4c`,subtitle:{zh:`同一個 if，四千筆以下 Node 快，一萬六千筆以上 Rust 快`,en:`The same if: below 4K items Node is faster, above 16K Rust is faster`},description:{zh:`4b 裡 Rust 贏過 Node，是因為資料不可預測。可是 4b 的陣列有一千萬筆，不可預測可能有兩個來源：值本身是隨機的，或是資料多到 CPU 記不住。這組要分出是哪一個。<br><br>做法是同一個 <code>if</code>、同樣的隨機資料，只改陣列長度，從一千筆到一百萬筆，量每個元素花的時間。總共讀取的元素數固定在兩億左右，所以陣列越短，同一個陣列就重複走越多遍。<br><br>CPU 會照這個 <code>if</code> 前幾次走的方向，猜下一次要走哪一條路，branch predictor 能記錄的走向數量有限。陣列短的話，同一串「進、不進」會一遍又一遍重複，整串都在記錄範圍裡，就幾乎每次猜對。所以要是 Node 慢是因為猜錯，它應該在陣列超過記錄範圍時才開始變慢。Rust 編譯成 <code>fcsel</code>，沒有分支，應該不受長度影響。`,en:`In 4b Rust beats Node because the data is unpredictable. But the 4b array has ten million items, so "unpredictable" could come from two sources: the values themselves are random, or there is too much data for the CPU to remember. This group separates the two.<br><br>The method: the same <code>if</code>, the same random data, only the array length changes, from one thousand items to one million, measuring the time per element.<br><br>The CPU guesses which way this <code>if</code> goes next based on the last few times, and it can remember only so much. With a short array the same sequence of outcomes repeats, so if the CPU can remember it, it guesses right. So if Node is slow because of wrong guesses, it should start slowing down only once the array is too long to remember. Rust has no branch and should not be affected by length.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
// The same loop, only the array length changes, the total number of elements visited is fixed
function branchy(arr) {
  let s = 0;
  for (let i = 0; i < arr.length; i++) {
    const y = arr[i] * 2;
    if (y > 1) s += y;      // on random data this if holds about half the time
  }
  return s;
}
\`\`\`

\`\`\`rust
// The Rust side compiles to fcsel, there is no branch to guess
fn branchy(arr: &[f64]) -> f64 {
    let mut s = 0.0;
    for &x in arr {
        let y = x * 2.0;
        if y > 1.0 { s += y; }
    }
    s
}
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`1 千`,en:`1K`},{zh:`4 千`,en:`4K`},{zh:`1.6 萬`,en:`16K`},{zh:`6.4 萬`,en:`64K`},{zh:`25.6 萬`,en:`256K`},{zh:`100 萬`,en:`1M`}],datasets:[e(`Node`,[1.021,.805,3.911,5.123,5.311,5.594],t.node),e(`Rust`,[1.547,1.592,1.582,1.569,1.583,1.6],t.rust)]},options:s(` ns`)},conclusion:{zh:`<p>Rust 從一千筆到一百萬筆，每個元素都是 1.58ns 左右，跨了三個數量級還是一條平線，因為它沒有分支要猜。</p><p>Node 在四千筆跟一萬六千筆之間跳了 4.9 倍，之後停在 5ns 左右。這是因為這台機器的 branch predictor 大約能記錄幾千筆的走向，陣列再長就超出範圍。</p><p>所以四千筆以下 Node 快，一萬六千筆以上 Rust 快。4b 裡 branch prediction 讓 Node 慢的那 1.72 倍，要資料隨機、而且陣列超出記錄範圍才會出現。</p>`,en:`<p>From one thousand items to one million, Rust takes about 1.58ns per element, a flat line across three orders of magnitude, because it has no branch to guess.</p><p>Node jumps 4.9 times between four thousand and sixteen thousand items, then stays at about 5ns. The branch predictor on this machine can remember the outcomes of a few thousand items; beyond that it cannot.</p><p>So below four thousand items Node is faster, and above sixteen thousand Rust is faster. The 1.72 times in 4b appears only when the data is random and too long to remember.</p>`}},{num:`5a`,subtitle:{zh:`整個程式只跑一次：Node 慢 2.7 到 3.7 倍`,en:`The whole program runs once: Node is 2.7 to 3.7 times slower`},description:{zh:`任務內容跟 build 工具差不多：讀一個 4.8MB 的檔、把註解行拿掉、字串換掉、寫回去。用 hyperfine（把同一條指令重跑很多次、給出平均跟標準差的 CLI）從外面量整個 process，所以 Node 啟動 V8 的時間也算進去。兩邊的輸出檔有 diff 過，確認做的是同一件事。`,en:`The task is close to what a build tool does: read a 4.8MB file, drop the comment lines, replace strings, write it back. hyperfine (a CLI that reruns the same command many times and reports the mean and standard deviation) measures the whole process from outside, so the time Node spends starting V8 is counted too. The output files of both sides were diffed to confirm they do the same thing.`},lang:`raw`,codeLabel:{zh:`JS / Rust / 指令`,en:`JS / Rust / Commands`},sql:`\`\`\`js
text.split("\\n")
  .filter((line) => !line.trimStart().startsWith("//"))
  .map((line) => line.replace(/const /g, "let ").toUpperCase())
  .join("\\n");
\`\`\`

\`\`\`rust
text.lines()
    .filter(|l| !l.trim_start().starts_with("//"))
    .map(|l| l.replace("const ", "let ").to_uppercase())
    .collect::<Vec<_>>()
    .join("\\n")
\`\`\`

\`\`\`bash
# Two sets back to back (bash run-all.sh ecold), output in results/e-cold.json and e-cold-2.json
hyperfine --warmup 2 --runs 40 'node e.js 1' './e-rust 1'
hyperfine --warmup 2 --runs 40 'node e.js 1' './e-rust 1'
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`第一組 40 次`,en:`First set, 40 runs`},{zh:`第二組 40 次`,en:`Second set, 40 runs`}],datasets:[e(`Node`,[62.9,61.1],t.node),e(`Rust`,[23.7,16.4],t.rust)]},options:s(`ms`)},conclusion:{zh:`<p>連著量兩組，每組 40 次，數字都是中位數。第一組 Node 62.9ms、Rust 23.7ms，Rust 快 2.65 倍。第二組 Node 61.1ms、Rust 16.4ms，Rust 快 3.72 倍。程式跑完就結束，所以 Node 啟動 V8 的時間也算在這一次裡面。</p><p class="caveat">兩組中間什麼都沒改，倍率卻從 2.65 變成 3.72，所以這個數字只能當大概的量級。兩組的 Node 只差 2ms，Rust 卻從 23.7ms 變成 16.4ms。Rust 整個任務只跑十幾毫秒，光是第二組的 40 次裡，最快 15.1ms、最慢 23.7ms 就差了 8ms。開 process 跟讀檔的時間只要整組偏慢一點，中位數就會跟著移動好幾毫秒，對十幾毫秒來說就是好幾成。第一組是緊接在重新編譯、重新產生輸入檔之後跑的，這可能是原因，但沒有驗證。</p>`,en:`<p>Two sets measured back to back, 40 runs each, all numbers medians. First set: Node 62.9ms, Rust 23.7ms, Rust 2.65 times faster. Second set: Node 61.1ms, Rust 16.4ms, Rust 3.72 times faster. The program exits as soon as it finishes, so the time Node spends starting V8 is counted in this one run.</p><p class="caveat">Nothing changed between the two sets, yet the ratio moved from 2.65 to 3.72, so the number only gives a rough order of magnitude. Node differs by only 2ms between the sets, while Rust goes from 23.7ms to 16.4ms. The whole Rust task takes a dozen or so milliseconds, and within the 40 runs of the second set alone it ranges from 15.1ms to 23.7ms, 8ms apart. If process start and file reads run a little slow across a whole set, the median moves by several milliseconds, which is a large share of a dozen or so. The first set ran right after the rebuild and the regenerated input file. That may be the cause, but it was not verified.</p>`}},{num:`5b`,subtitle:{zh:`一樣的任務重複三百次：差距縮到 1.48 倍`,en:`The same task three hundred times: the gap shrinks to 1.48 times`},description:{zh:`跟 5a 是同一份程式，處理字串的那段 code 一個字都沒改，只把重複次數從 1 改成 300。次數是從命令列傳進去的，所以兩張圖跑的是同一個執行檔。`,en:`The same program as 5a; the code that handles the strings is unchanged, and only the repeat count goes from 1 to 300. The count is passed on the command line, so both charts run the same executable.`},lang:`raw`,codeLabel:{zh:`JS / Rust / 指令`,en:`JS / Rust / Commands`},sql:`\`\`\`js
// e.js: the count comes from the argument, the transform is exactly the same as the previous chart
const loops = parseInt(process.argv[2] || "1", 10);
const src = fs.readFileSync("input.txt", "utf8");

let out = "";
for (let i = 0; i < loops; i++) out = transform(src);
fs.writeFileSync("out-js.txt", out);
\`\`\`

\`\`\`rust
// e.rs: also from the argument
let loops: usize = env::args().nth(1).and_then(|s| s.parse().ok()).unwrap_or(1);
let src = fs::read_to_string("input.txt").expect("run gen-input.js first");
let mut out = String::new();
for _ in 0..loops {
    out = transform(&src);
}
fs::write("out-rust.txt", out).unwrap();
\`\`\`

\`\`\`bash
# Previous chart: one run. This chart: three hundred runs. Same executable, only the argument differs.
hyperfine --warmup 2 --runs 20 'node e.js 1'   './e-rust 1'
hyperfine --warmup 1 --runs 5  'node e.js 300' './e-rust 300'
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`同一任務重複 300 次`,en:`Same task, 300 repeats`}],datasets:[e(`Node`,[5.51],t.node),e(`Rust`,[3.73],t.rust)]},options:s(`s`)},conclusion:{zh:`<p>在同一個 process 裡跑三百次，Node 要 5.51 秒，Rust 要 3.73 秒，差距從只跑一次時的 2.7 到 3.7 倍，縮到 1.48 倍。</p><p>只跑一次的時候，Node 慢的地方大多在啟動。<code>node -e 0</code> 什麼事都不做，平均也要 35ms 左右，而 Rust 把整個任務跑完只要 16 到 24ms。</p><p>JIT 在只跑一次時也幾乎沒有作用。同一支程式加上 <code>--jitless</code>，讓 V8 不做 JIT 編譯，Node 跑一次是 64ms，預設是 60ms，差距在誤差範圍內。可是重複三百次時，JIT 就有作用了。這是 2026-10-22 另外跑的一組，Node 預設要 5.3 秒，加上 <code>--jitless</code> 要 7.0 秒，多花了 30% 的時間。</p><p>所以只跑一次時的 2.7 到 3.7 倍，大半來自 Node 的啟動時間。同一個任務用兩種語言各寫一次，差距在 1.48 到 3.7 倍之間，離 SWC 宣稱的 20 到 70 倍還很遠。</p>`,en:`<p>Running three hundred times in one process, Node takes 5.51 seconds and Rust 3.73 seconds, so the gap shrinks from 2.7 to 3.7 times in a single run to 1.48 times.</p><p>In a single run, most of Node's extra time goes to starting up. <code>node -e 0</code>, which does nothing, takes about 35ms on average, while Rust finishes the whole task in 16 to 24ms.</p><p>In a single run the JIT also does almost nothing. With <code>--jitless</code>, so V8 does no JIT compilation, one Node run takes 64ms against 60ms by default, a gap within the noise. Over three hundred repetitions, though, the JIT matters. In a separate set run on 2026-10-22, Node took 5.3 seconds by default and 7.0 seconds with <code>--jitless</code>, 30% more time.</p><p>So most of the 2.7 to 3.7 times in a single run comes from Node's startup time. The same task written once in each language differs by 1.48 to 3.7 times, still far from the 20 to 70 times SWC claims.</p>`}},{num:`5c`,subtitle:{zh:`換成走訪 AST：Rust 快 2.68 倍，差距沒有變大`,en:`Switch to an AST walk: Rust is 2.68 times faster, and the gap does not grow`},description:{zh:`前面幾組都是很單純的迴圈和字串處理，差距會不會只是因為情境太單純？這組換成最像 parser 和 transformer 的工作：建一棵有 178 萬個節點的 AST（abstract syntax tree），節點分成六種型別（Ident、Num、Bin、Call、Unary、Block），再遞迴走訪一遍，每個節點依型別分開處理。<br><br>這份工作有大量的小物件，每個 AST 節點都是一個。同一個處理函式也會遇到六種結構不同的物件，V8 在同一個呼叫位置遇到的物件結構越多種，就越難優化。每個節點是哪一種型別，照一串固定的整數決定，兩邊用的是同一串，建出來的節點數跟 checksum 也一致，所以兩邊走訪的是同一棵 AST。`,en:`The previous groups were all plain loops and string handling. Is the gap small only because the setting is too simple? This group switches to the work closest to a parser and transformer: build an AST (abstract syntax tree) of 1.78 million nodes in six node types (Ident, Num, Bin, Call, Unary, Block), then walk it recursively, handling each node by its type.<br><br>This work has a large number of small objects, one per AST node. The same handler also meets six objects of different shape, and the more shapes V8 sees at one call site, the harder it is to optimize. Each node's type comes from a fixed sequence of integers that both sides share, and both produce the same node count and checksum, so both walk the same AST.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
// JS: objects carry a type field, dispatch with switch
function walk(node) {
  switch (node.type) {
    case "Ident": return node.name.length;
    case "Num":   return node.value > 50 ? 1 : 0;
    case "Bin":   return walk(node.left) + walk(node.right);
    case "Unary": return walk(node.arg);
    // Call and Block walk their own children
  }
}
\`\`\`

\`\`\`rust
// Rust: enum + match, the types are sorted out at compile time
fn walk(node: &Node) -> i64 {
    match node {
        Node::Ident(name) => name.len() as i64,
        Node::Num(v) => if *v > 50 { 1 } else { 0 },
        Node::Bin(l, r) => walk(l) + walk(r),
        Node::Unary(a) => walk(a),
        // Call and Block walk their own children
    }
}
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`走訪 178 萬個節點`,en:`Walk 1.78M nodes`}],datasets:[e(`Node`,[39.62],t.node),e(`Rust`,[14.79],t.rust)]},options:s(`ms`)},conclusion:{zh:`Node 39.62ms，Rust 14.79ms，Rust 快 2.68 倍。5a 只跑一次的倍率是 2.7 到 3.7 倍，這裡接近其中最小的那一頭。換成走訪 AST 這種最像 bundler 的工作，倍率也沒有變大，所以 1a 到 5b 的倍率不大，不是因為情境太單純。語言本身在同一件工作上大約是 3 倍，SWC 宣稱的是 20 倍。3 倍到 20 倍之間的那一段，要到 6b 拿 Babel 跟 SWC 實際比過才知道。`,en:`Node 39.62ms, Rust 14.79ms, Rust 2.68 times faster, at the low end of the 2.7 to 3.7 times in 5a. On the work closest to a bundler the gap does not grow, so the earlier gaps were not small because the setting was too simple. On the same job the language itself is about 3 times, far from the 20 times SWC claims; 6b measures the part in between with Babel and SWC, the tools in real use.`}},{num:`6a`,subtitle:{zh:`多核心：開到八個執行緒，Node 快 6.2 倍，Rust 快 7.6 倍`,en:`Multiple cores: with eight threads, Node gets 6.2 times faster and Rust 7.6 times`},description:{zh:`前面所有組都是單執行緒對單執行緒，所以「Rust 比較快」跟「原生工具用上所有核心」這兩件事一直混在一起。這組把它們分開：同一個 AST 走訪，兩邊各用 1、2、4、8 個執行緒跑。Node 用的是內建的 worker_threads，所以 JavaScript 一樣能用多核心。<br><br>兩邊的限制不一樣。Node 的 worker 之間不能共用物件，所以每個 worker 都要自己建一份 AST；Rust 的執行緒可以用 <code>Arc</code> 共用同一份。為了讓比較公平，建 AST 的時間不算在計時裡，每個 worker 建完才回報 ready，全部就緒之後才開始計時。不過在真的工具裡，複製 AST 的成本還是在。兩邊、四種執行緒數一共八組，checksum 全部是 55614200，所以它們做的是同一份工作。`,en:`All previous groups were single thread against single thread, so "Rust is faster" and "native tools use every core" stayed mixed together. This group separates them: the same AST walk, with each side running on 1, 2, 4 and 8 threads. Node uses the built in worker_threads, so JavaScript can use multiple cores too.<br><br>The two sides have different limits. Node workers cannot share objects, so each worker builds its own AST; Rust threads can share one copy through <code>Arc</code>. To keep the comparison fair, building the AST is not timed: each worker reports ready only after building, and timing starts once all are ready. In a real tool, though, the cost of copying the AST is still there. Across both sides and four thread counts, all eight runs give checksum 55614200, so they all do the same work.`},lang:`raw`,codeLabel:`JS / Rust`,sql:`\`\`\`js
// Node: worker_threads, each worker builds its own AST (building is not timed)
const w = new Worker(__filename, { workerData: { walks: per } });
w.on("message", (msg) => {
  if (msg === "ready" && ++ready === threads) {
    start = process.hrtime.bigint();          // start timing only when all are ready
    workers.forEach((x) => x.postMessage("go"));
  }
});
\`\`\`

\`\`\`rust
// Rust: thread::spawn, share one AST through Arc, no copy needed
let handles: Vec<_> = (0..threads).map(|_| {
    let t = Arc::clone(&tree);
    thread::spawn(move || {
        let mut s = 0i64;
        for _ in 0..per { s += walk(black_box(&t)); }
        s
    })
}).collect();
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`1 執行緒`,en:`1 thread`},{zh:`2 執行緒`,en:`2 threads`},{zh:`4 執行緒`,en:`4 threads`},{zh:`8 執行緒`,en:`8 threads`}],datasets:[e(`Node`,[1521.5,816.8,408.4,244.4],t.node),e(`Rust`,[542.9,270.5,141,71.8],t.rust)]},options:s(`ms`)},conclusion:{zh:`<p>1 到 4 個執行緒時，Rust 比 Node 快的倍率維持在三倍上下：1 個 2.80 倍、2 個 3.02 倍、4 個 2.90 倍。到 8 個執行緒拉開到 3.40 倍，三輪各是 3.24、3.89、3.40，每一輪都比 1 到 4 個執行緒時高。</p><p>從 1 個到 8 個執行緒，Node 從 1521.5ms 降到 244.4ms，快了 6.23 倍；Rust 從 542.9ms 降到 71.8ms，快了 7.56 倍。三輪都是 Rust 加速得比較多。</p><p>不過 Node 自己也快了六倍。所以 SWC 宣稱的「四核心快 70 倍」裡，多核心帶來的那一部分，JavaScript 工具也能用到大半，只是 Babel 沒有用多核心。</p><p class="caveat">數字是三輪的中位數，原始輸出在 <code>results/par.txt</code>。一開始的設計有個錯：1 個執行緒時直接在主執行緒跑，2 個以上才建 worker，所以從 1 個換到 2 個時，執行緒數跟有沒有 worker 同時變了。現在四種設定都經過 worker，只有數量在變。修正前我報的是 7.20 倍和 8.13 倍，那是除以沒有 worker 成本的單執行緒時間，而且只跑了一輪，所以偏高。8 個執行緒的 Node 在三輪裡是 239.5、277.2、244.4ms，起伏不小，所以這裡的倍率只能當大概的量級。</p>`,en:`<p>From 1 to 4 threads, Rust stays about three times faster than Node: 2.80 at 1 thread, 3.02 at 2, 2.90 at 4. At 8 threads it widens to 3.40; the three rounds give 3.24, 3.89 and 3.40, each higher than at 1 to 4 threads.</p><p>From 1 to 8 threads, Node goes from 1521.5ms to 244.4ms, 6.23 times faster; Rust from 542.9ms to 71.8ms, 7.56 times faster. Rust gained more in all three rounds.</p><p>Still, Node alone got six times faster. So of SWC's claimed "70 times faster on four cores", most of the part that comes from multiple cores is available to a JavaScript tool too; Babel just does not use multiple cores.</p><p class="caveat">The numbers are the median of three rounds; the raw output is in <code>results/par.txt</code>. The first design had a mistake: with 1 thread it ran directly on the main thread and only created workers from 2 threads up, so going from 1 to 2 changed both the thread count and whether workers were used. Now all four settings go through workers, and only the count changes. Before the fix I reported 7.20 and 8.13 times; those divided by a single thread time with no worker cost and came from one round, so they were too high. The 8 thread Node time was 239.5, 277.2 and 244.4ms across the three rounds, a wide spread, so the ratios here only give a rough order of magnitude.</p>`}},{num:`6b`,subtitle:{zh:`三個實際在用的工具：Go 寫的 esbuild 也比 Babel 快五倍`,en:`Three tools in real use: esbuild, written in Go, is also five times faster than Babel`},description:{zh:`1a 到 5c 量的都是語言，同一份演算法寫兩遍。這組量的是實際在用的工具：Babel 8.0.1（JavaScript）、SWC 1.15.46（Rust）、esbuild 0.28.1（Go）。三個工具把同一份 280KB 的檔案編譯到同一個目標，全部用單執行緒。<br><br>SWC 比 Babel 快這麼多，是因為 Rust 這個語言，還是因為它編譯成原生執行檔、又是從頭設計的工具？我拿 esbuild 來分辨這兩種可能。esbuild 跟 SWC 一樣編譯成原生執行檔、也是從頭設計的，但它用 Go 寫，Go 跟 Rust 的差別也不只語法，例如 Go 有 GC、Rust 沒有。如果快只來自 Rust 這個語言，esbuild 應該跟 Babel 一樣慢。如果快來自原生執行檔加上重新設計，esbuild 應該接近 SWC，離 Babel 很遠。<br><br>編譯目標選 ES2019，是因為三個工具都支援。ES5 是 2009 年 12 月的標準，ES2019 是 2019 年 6 月，中間差了將近十年。編譯成 ES2019，只要改寫 optional chaining、nullish coalescing、class 私有欄位這些 2020 年之後才進標準的語法；編譯成 ES5 的話，ES2015 之後加進來的語法都要改寫，像 class、箭頭函式、let 和 const、async、generator，其中 async 跟 generator 還得整個改寫成狀態機。<a href="https://swc.rs/" target="_blank" rel="noopener">SWC 官網</a>宣稱「20x faster than Babel on a single thread and 70x faster on four cores」，這組自己實際量一次。`,en:`1a to 5c all measured the language, the same algorithm written twice. This group measures tools in real use: Babel 8.0.1 (JavaScript), SWC 1.15.46 (Rust) and esbuild 0.28.1 (Go). All three compile the same 280KB file to the same target, on a single thread.<br><br>esbuild is here to test one question: is SWC this much faster because of the Rust language, or would any tool that compiles to a native executable and was designed from scratch be just as fast? Like SWC, esbuild compiles to a native executable and was designed from scratch, but it is written in Go, and Go differs from Rust in more than syntax: Go has a GC, Rust does not. If the speed came only from the Rust language, esbuild should be as slow as Babel. If it comes from a native executable plus a fresh design, esbuild should be close to SWC and far from Babel.<br><br>ES2019 is the target because all three tools support it. ES5 is the standard from December 2009 and ES2019 from June 2019, almost ten years apart. Compiling to ES2019 only rewrites syntax that entered the standard from 2020 on, such as optional chaining, nullish coalescing and class private fields; compiling to ES5 rewrites everything added from ES2015 on, such as class, arrow functions, let and const, async and generator, and async and generator must be rewritten entirely as state machines. The <a href="https://swc.rs/" target="_blank" rel="noopener">SWC website</a> claims "20x faster than Babel on a single thread and 70x faster on four cores"; this group measures it directly.`},lang:`raw`,codeLabel:{zh:`JS / 指令`,en:`JS / Commands`},sql:`\`\`\`js
// Same input, both compile to the same target, both on the caller's single thread
babel.transformSync(src, {
  presets: [["@babel/preset-env", { targets: { ie: "11" }, modules: false }]],
});

swc.transformSync(src, {
  jsc: { target: "es5", parser: { syntax: "ecmascript" } },
});
\`\`\`

\`\`\`bash
cd babel-vs-swc
npm install
node gen.js     # generate the 280KB, 10000 line input
node bench.js   # one process: 8 reps per tool per target, prints the medians
# The numbers below: bash run-all.sh bs, six processes, output in results/bs.txt
\`\`\`

Median of the six processes, range in brackets (the ratio is always Babel time divided by SWC time):

\`\`\`text
Target ES2019   Babel  134.0ms (120-135)    SWC 19.6ms (17-21)   esbuild 25.6ms (23-26)   SWC  6.8x faster
Target ES5      Babel 4385ms  (4065-4850)   SWC 78.1ms (74-82)   esbuild fails            SWC   56x faster
\`\`\``,chart:{type:`bar`,data:{labels:[`Babel
(JavaScript)`,`SWC
(Rust)`,`esbuild
(Go)`],datasets:[e({zh:`編譯成 ES2019（中位數）`,en:`Target ES2019 (median)`},[134,19.6,25.6],t.node)]},options:s(`ms`)},conclusion:{zh:`<p>六次執行的範圍：Babel 120 到 135ms，SWC 17 到 21ms，esbuild 23 到 26ms。esbuild 每一次都比 SWC 慢，慢 27% 到 38%，但兩個都比 Babel 快五倍以上，SWC 快 6.4 到 7.7 倍，esbuild 快 5.0 到 5.9 倍。所以結果比較接近上面說的第二種可能。</p><p>要快到這個程度，不一定要用 Rust，Go 寫的工具也比 Babel 快五倍以上。</p><p>5c 用同一份演算法量，Rust 比 Node 快 2.68 倍，這是換語言本身的效果。這裡編譯到 ES2019，Rust 寫的 SWC 比 JavaScript 寫的 Babel 快 6.8 倍。6.8 除以 2.68 還剩 2.5 倍，這 2.5 倍跟語言無關，是 SWC 跟 Babel 兩個程式之間的差別。</p><p>編譯成 ES5 時差距更大，Babel 4065 到 4850ms，SWC 74 到 82ms，SWC 快 50 到 62 倍。esbuild 在這個目標直接失敗，回報 7200 個錯誤，因為它不支援把 async 跟 generator 轉成 ES5 的寫法。所以 ES5 只能比 Babel 跟 SWC。</p><p class="caveat">數字來自六個 process，原始輸出在 <code>results/bs.txt</code>。先前我只跑兩次就說「同條件重跑幾乎不動」，那是樣本太少；跑了六次之後，ES5 的倍率在 50 到 62 之間變動，所以這個數字只能當量級看。另外三邊的輸出大小都不一樣，Babel 是 307KB，SWC 是 490KB，esbuild 是 366KB，產生的程式碼不同，所以做的工作不完全對等。我也試過只比 parser 來避開這個問題，結果 SWC 的 parseSync 反而比較慢（51.1ms 對 Babel 的 22.0ms），因為它要先把 AST 序列化成 JSON，才能交回 JavaScript。</p>`,en:`<p>The range over six runs: Babel 120 to 135ms, SWC 17 to 21ms, esbuild 23 to 26ms. esbuild is 27 to 38% slower than SWC in every run, but both are more than five times faster than Babel: SWC by 6.4 to 7.7 times, esbuild by 5.0 to 5.9 times. So the result is closer to the second possibility above.</p><p>Reaching this speed does not require Rust; a tool written in Go is also more than five times faster than Babel.</p><p>5c measured the same algorithm in both languages: Rust is 2.68 times faster, which is what changing the language buys. Here, compiling to ES2019, SWC (written in Rust) is 6.8 times faster than Babel (written in JavaScript). 6.8 divided by 2.68 leaves 2.5 times, which has nothing to do with the language: it is the difference between the SWC and Babel programs.</p><p>Compiling to ES5 the gap is larger: Babel 4065 to 4850ms, SWC 74 to 82ms, SWC 50 to 62 times faster. esbuild fails outright on this target with 7200 errors, because it does not support rewriting async and generator into ES5. So for ES5 only Babel and SWC can be compared.</p><p class="caveat">The numbers come from six processes; the raw output is in <code>results/bs.txt</code>. Earlier I ran only twice and said "rerunning under the same conditions barely moves"; that was too few samples. Over six runs the ES5 ratio moves between 50 and 62, so that number only gives the order of magnitude. Also, the three output sizes all differ, Babel 307KB, SWC 490KB and esbuild 366KB; the generated code differs, so the work is not fully equivalent. I also tried comparing only the parser to get around this, and SWC's parseSync turned out slower (51.1ms against Babel's 22.0ms), because it has to serialize the AST to JSON before handing it back to JavaScript.</p>`}}]},{id:`lang-ops-per-sec`,title:{zh:`一秒能做幾次操作：9 個語言對「10⁸ 規則」的實際刻度`,en:`How many operations in one second: 9 languages measured against the "10⁸ rule"`},date:`2026-08-05`,env:{zh:`Apple M1 Pro (arm64，8 個效能核心 + 2 個節能核心), macOS 15.6, 插電。clang 17.0.0 -O2 / rustc 1.97.1 -O / go 1.26.1 / Node v22.22.3 / Bun 1.3.14 / CPython 3.14.6 / PyPy 7.3.23 / OpenJDK 17.0.19 / Ruby 4.0.6`,en:`Apple M1 Pro (arm64, 8 performance cores + 2 efficiency cores), macOS 15.6, on mains power. clang 17.0.0 -O2 / rustc 1.97.1 -O / go 1.26.1 / Node v22.22.3 / Bun 1.3.14 / CPython 3.14.6 / PyPy 7.3.23 / OpenJDK 17.0.19 / Ruby 4.0.6`},summary:{zh:`估一個解法會不會超時，USACO Guide 給的數字是一秒 10⁸ 次操作。那句話講的是解題網站的 grading server，換成 Python、換成查 hashmap 還準不準，它沒有說。這輪用同一個演算法、同一組輸入，讓 9 個語言各跑 7 個獨立 process。實測下來這條線的誤差從 0.05 倍到 46 倍都有。9 個語言跑純迴圈，最快到最慢差 119 倍；跑 hashmap 只差 6.8 倍，而且 9 個語言全部低於 1。同一個 C++，跑純迴圈比跑 hashmap 快 178 倍，比它跟其他任何語言的差距都大。中途整組作廢重跑過一次，原因是迴圈攤在 main 裡，JIT 沒有正常編譯它。`,en:`To estimate whether a solution will time out, USACO Guide gives the number 10⁸ operations per second. That sentence is about the grading server of a judge site. Whether it still holds for Python, or for hashmap lookups, it does not say. This round uses the same algorithm and the same input, and runs 9 languages in 7 independent processes each. Measured, the error of that line ranges from 0.05x to 46x. On a plain loop the 9 languages differ by 119x from fastest to slowest; on hashmap only 6.8x, and all 9 languages are below 1. The same C++ runs a plain loop 178x faster than a hashmap, a larger gap than between it and any other language. Halfway through, the whole set was discarded and rerun once, because the loop sat in main and the JIT did not compile it normally.`},intro:{zh:`<p>表格裡每個數字是實測的 ops/sec 除以 <b>10⁸</b>。USACO Guide 估時限用的就是這個數，一秒 10⁸ 次操作。出處是 USACO Guide 的 Time Complexity 頁：<i>"A conservative estimate for the number of operations the grading server can handle per second is 10^8, but it could be closer to 5⋅10^8 given good constant factors."</i>（<a href="https://usaco.guide/bronze/time-comp" target="_blank" rel="noopener">usaco.guide/bronze/time-comp</a>）</p><p>C++ 跑純迴圈實測每秒 46.4 億次，除以 10⁸ 得到 46.4，表格就寫 46.4x，代表同一題照 10⁸ 估的時候，C++ 實際上跑得比估的快 46 倍。CPython 跑同一個迴圈實測每秒 1321 萬次，除以 10⁸ 得到 0.13。低於 1 代表 10⁸ 對 CPython 是高估，照它估會超時。</p><h3>一次操作指什麼</h3><p>USACO 的 10⁸ 是 grading server 的保守估計，沒說一次操作指的是什麼，也沒分語言。這輪在 M1 Pro 上量三種操作，每種都拿 10⁸ 當對照線：</p><table><tbody><tr><td><b>工作</b></td><td><b>規模</b></td><td><b>在量什麼</b></td><td><b>一次操作</b></td></tr><tr><td>埃氏篩</td><td>n = 5×10⁶</td><td>陣列隨機寫入、記憶體</td><td>內迴圈標記一次，共 11,192,870 次</td></tr><tr><td>純迴圈</td><td>跑 10⁸ 次</td><td>ALU、迴圈本體</td><td>迴圈跑一圈，共 10⁸ 次</td></tr><tr><td>hashmap</td><td>插入 + 查詢各 10⁶</td><td>雜湊、指標追逐</td><td>插入或查詢一次，共 2×10⁶ 次</td></tr></tbody></table><p class="note">埃氏篩的操作數不是 n。實際跑的是內迴圈的標記次數，數出來是 11,192,870，全語言共用這個分母。</p><p>量完的結果，CPython 三種操作都落在每秒 10⁷ 上下，dict 操作接近 5×10⁶，所以用 CPython 估時限，拿 10⁷ 比 10⁸ 準。</p><h3>9 個語言的編譯時機跟記憶體管理</h3><table><tbody><tr><td></td><td><b>什麼時候變成 machine code</b></td><td><b>記憶體誰管</b></td></tr><tr><td>C++、Rust</td><td>執行之前就編譯好（AOT，Ahead Of Time）</td><td>自己管，變數出了作用域就釋放</td></tr><tr><td>Go</td><td>執行之前就編譯好</td><td>GC（Garbage Collector）</td></tr><tr><td>Java</td><td>先編譯成 bytecode，執行時 JIT（Just In Time）再編譯成 machine code</td><td>GC</td></tr><tr><td>Node、Bun</td><td>執行時才編譯，JIT。Node 用 V8，Bun 用 JavaScriptCore</td><td>GC</td></tr><tr><td>PyPy</td><td>執行時才編譯，JIT</td><td>GC</td></tr><tr><td>CPython、Ruby</td><td>編譯成 bytecode 之後一條一條直譯，沒有 JIT</td><td>GC</td></tr></tbody></table><p>AOT 語言第 1 輪就是全速，JIT 語言要跑幾輪才會編譯到最好（第 4 組量了 Java，68ms 跑到 37ms），直譯器則是每一輪都一樣慢。C++ 自己管記憶體，在計時區間內逐個釋放 hashmap 那 100 萬個節點，多花 15.7ms（第 6 組）。</p><p><b>PyPy 跟 CPython 是同一個語言的 2 份實作。</b>同一個 <code>.py</code> 檔，兩邊都能執行。CPython 是官方那份，把程式碼編譯成 bytecode 之後一條一條執行；PyPy 多了一個 JIT，跑很多次的迴圈會被編譯成 machine code。純迴圈 PyPy 快 85 倍，埃氏篩快 6.2 倍，hashmap 只快 3.6 倍。</p><table><tbody><tr><td></td><td><b>埃氏篩</b><br>陣列寫入</td><td><b>純迴圈</b><br>ALU</td><td><b>hashmap</b><br>雜湊查找</td></tr><tr><td>C++ (clang -O2)</td><td>9.55x</td><td>46.4x <i>SIMD</i></td><td>0.26x <i>釋放</i></td></tr><tr><td>Rust (rustc -O)</td><td>9.6x</td><td>45.1x <i>SIMD</i></td><td>0.34x</td></tr><tr><td>Go</td><td>11.8x</td><td>15.7x</td><td>0.2x</td></tr><tr><td>Java 17</td><td>8.52x</td><td>26.8x</td><td>0.13x</td></tr><tr><td>Bun 1.3</td><td>3.78x</td><td>12.0x</td><td>0.09x</td></tr><tr><td>PyPy 3.11</td><td>1.39x</td><td>11.2x</td><td>0.18x</td></tr><tr><td>Node 22</td><td>2.84x</td><td>10.2x</td><td>0.05x</td></tr><tr><td>Ruby 4.0</td><td>0.2x</td><td>0.2x</td><td>0.06x</td></tr><tr><td>CPython 3.14</td><td>0.22x</td><td>0.13x</td><td>0.05x</td></tr></tbody></table><p class="note"><i>SIMD</i>（Single Instruction Multiple Data）是編譯器把內迴圈改寫成一道指令同時算 8 筆資料，所以 C++ 跟 Rust 這兩個數字的「一次操作」跟其他語言的一次一筆不同義。<i>釋放</i> 是 C++ 在計時區間內就要把 hashmap 佔的記憶體還回去，而且這一步很貴：<code>unordered_map</code> 的 100 萬筆是 100 萬個獨立配置的節點，釋放要呼叫 100 萬次 <code>free</code>，花掉 15.7ms（第 6 組）。Rust 也在同一個點釋放，但它的 <code>HashMap</code> 是一塊連續配置，還一次就好，量出來是 0，所以 Rust 那個數字不用標。扣掉之後 C++ 跑 hashmap 是 <b>0.33x</b>，跟 Rust 的 0.34x 幾乎一樣。這個 0.33x 是拿 76.89ms 減 15.7ms 換算的。</p><h3>為什麼同一個語言的 3 個數字差這麼多</h3><p><b>同樣這 9 個語言，跑純迴圈差 119 倍，跑 hashmap 只差 6.8 倍。</b>純迴圈那一欄，沒有用 SIMD 的語言裡最快的 Go 每秒 15.7 億次，最慢的 CPython 1321 萬次。hashmap 那一欄，最快的 Rust 到最慢的 CPython 只差 6.8 倍。所以一題如果時間都花在 hashmap 存取，把 CPython 改寫成 C++ 只會快 5 倍左右；同一題如果時間花在純算術的迴圈，改寫成 Go 會快 119 倍。</p><p class="caveat">那 6.8 倍只在 hashmap 這一欄的工作內容上成立，而它的內容是插入 100 萬次加查詢 100 萬次，各佔一半。插入要配置 100 萬個節點，這一步對 C++ 特別貴（它 hashmap 每次操作 38.4ns，純查詢只要 9.0ns，4.3 倍），對 CPython 幾乎沒有負擔（197.5ns 對 243.3ns，0.8 倍）。這 4.3 倍是概數：主表的查詢一半命中一半落空，落空的比命中便宜，而純查詢那組全部命中，兩邊的「一次查詢」不是同一種。換句話說，把語言差距縮到 6.8 倍的有一大半是插入那一段。換成純查詢（100 萬筆的 map 查 200 萬次），同樣 9 個語言最慢除以最快是 <b>27.2 倍</b>，CPython 改寫成 C++ 快 27 倍不是 5 倍。所以「換語言快不了多少」只在插入跟查詢各佔一半的 hashmap 題上成立。</p><p><b>同一個語言，不同操作也差一樣多。</b>C++ 跑純迴圈每秒 46.4 億次，跑 hashmap 只有 2601 萬次，中間差 178 倍。所以「C++ 一秒跑 10⁹」這句話只在 CPU 密集、而且資料放在連續記憶體的迴圈上成立。拿它去估一個 hashmap 吃重的解法，就是差這 178 倍。</p><p><b>C++ 跑 hashmap 一次操作 30.6ns，其中 7.44ns 跟資料放不放得進快取有關。</b>（30.6ns 是扣掉釋放那 15.7ms 之後換算的，理由見第 6 組。）對照組是同一個 C++ 跑純迴圈的一步 0.22ns。那 7.44ns 是量出來的：C++ 在 1000 筆的 map 裡查詢一次要 1.51ns，換成 100 萬筆的 map 要 8.95ns，只有 map 大小變。等記憶體要多久，用 pointer chasing（指標追逐）量了這台機器讀一個值要等多久（陣列每個元素存的是下一個元素的位置，所以下一次要讀哪裡得等這一次讀回來，CPU 沒辦法把等待疊在一起）：</p><table><tbody><tr><td><b>資料總量</b></td><td><b>一次讀取要等</b></td><td></td></tr><tr><td>16 KB</td><td>1.25 ns</td><td>在 L1 裡（L1d 128KB）</td></tr><tr><td>256 KB</td><td>3.72 ns</td><td>L1 裝不下，落到 L2（12MB）</td></tr><tr><td>4 MB</td><td>6.69 ns</td><td></td></tr><tr><td>32 MB</td><td>89.59 ns</td><td>主記憶體</td></tr><tr><td>128 MB</td><td>123.60 ns</td><td></td></tr></tbody></table><p class="caveat">這張表量的是「一次只能等一個」的延遲，因為指標追逐讓 CPU 一次只能發一個讀取。真實的程式多半不是這樣：位址如果先算得出來，CPU 可以同時發好幾個出去，等待疊在一起。同一塊 64MB、同一批隨機位址，只把「下一個位址要不要等這次讀回來」拿掉，一次讀取從 120ns 降到 4ns，30 倍。所以這張表量到的是一條相依鏈上的延遲，每次讀取實際攤到的時間比這少。</p><p>CPU 一次搬 128 bytes（<code>sysctl hw.cachelinesize</code>），不是只搬程式要的那 8 bytes。埃氏篩的內迴圈一路往前走，所以每 128 bytes 才真的等一次。而且它的位址有規律，每次 +i。CPU 裡有一塊叫 prefetcher 的電路專門找這種規律，找到就先把下一塊搬進快取，連那一次也省掉。</p><p>hashmap 的位址既不連續、也沒有規律，所以一次搬 128 bytes 跟 prefetcher 都幫不上忙。bucket 的位址是 hash 算出來的，這次讀第 3 個 bucket、下次讀第 90 萬個，上次搬進來的那 128 bytes 裡沒有下次要的資料，prefetcher 也找不出規律。而且要等 hash 算完才知道位址，那個 bucket 讀回來才知道裡面存的 key 是不是要找的，這條鏈只能一步一步走。</p><p>但查詢跟查詢之間是獨立的，CPU 可以同時發好幾個出去，所以 map 變大之後每次查詢多出來的不是那 90ns，是上面那 7.44ns。這個量級跟不相依存取的 4ns 差不多，離相依鏈的 120ns 差了十幾倍。（100 萬筆的 <code>unordered_map</code> 實際佔 56.1MB，量的是常駐記憶體，每筆 58.8 bytes，因為每筆是一個獨立配置的節點加上一個有 1,646,237 個 bucket 的陣列。）</p><p><b>10⁸ 對 CPython 高估 4 到 20 倍。</b>CPython 那 3 個數字分別是 0.22、0.13、0.05，全部低於 1。0.05 是 dict：2×10⁶ 次操作要 0.39 秒，一題如果要跑 10⁷ 次 dict 操作，CPython 要花 2 秒。所以估 CPython 的時候，該用的基準是一秒 10⁷ 次上下，dict 操作慢一些，接近 5×10⁶，不是 10⁸。</p><h3>怎麼量的</h3><p>一個語言配一種工作算一組，每組開 7 個獨立 process，每個 process 內跑 5 次，所以是 35 次計時。每個 process 的第 1 次當 warmup 丟掉，中位數取自剩下的 28 次。中位數旁邊那個 <code>±</code> 是 <b>IQR（Interquartile Range，四分位距）</b>：把 28 個時間從小到大排好，砍掉最小的四分之一跟最大的四分之一，剩下中間那一半有多寬。它是拿來看那一組穩不穩的。Java 跑純迴圈是 37.26ms ± 14.59，中間一半的樣本散在比中位數四成還寬的範圍裡；C++ 跑純迴圈是 21.56ms ± 0.84，中間一半幾乎疊在一起。用 IQR 不用標準差，是因為一次 GC 或系統排程造成的 outlier 會把標準差拉大，IQR 不理會頭尾那兩塊。203 個 process 的跑序隨機化（固定種子）。機器連續跑會升溫降頻，不隨機化的話這個影響會固定落在最後跑的那個語言身上。每個語言跑完都要印出自己算出來的答案（埃氏篩是質數個數 348513，純迴圈是加總值，hashmap 是 map 大小加上命中值的總和）。9 個語言印出來的答案只要有一個跟其他語言不一樣，就代表有人實作錯了，那組作廢重寫。同一個目標在整輪的頭尾各跑一次當漂移對照，結尾比開頭快 1.3%，所以小於 5% 的差距在這輪讀不出來。</p>`,en:`<p>Every number in the table is the measured ops/sec divided by <b>10⁸</b>. That is the number USACO Guide uses to estimate time limits: 10⁸ operations per second. The source is the Time Complexity page of USACO Guide: <i>"A conservative estimate for the number of operations the grading server can handle per second is 10^8, but it could be closer to 5⋅10^8 given good constant factors."</i>(<a href="https://usaco.guide/bronze/time-comp" target="_blank" rel="noopener">usaco.guide/bronze/time-comp</a>)</p><p>C++ on a plain loop measures 4.64 billion per second. Divided by 10⁸ that is 46.4, so the table says 46.4x, meaning that when the same problem is estimated with 10⁸, C++ actually runs 46 times faster than the estimate. CPython on the same loop measures 13.21 million per second. Divided by 10⁸ that is 0.13. Below 1 means 10⁸ overestimates CPython. Estimate with it and the solution times out.</p><h3>What one operation means</h3><p>The USACO 10⁸ is a conservative estimate for the grading server. It does not say what one operation is, and it does not separate languages. This round measures three kinds of operation on the M1 Pro, each against 10⁸ as the reference line:</p><table><tbody><tr><td><b>Workload</b></td><td><b>Size</b></td><td><b>What it measures</b></td><td><b>One operation</b></td></tr><tr><td>sieve</td><td>n = 5×10⁶</td><td>random array writes, memory</td><td>one mark in the inner loop, 11,192,870 in total</td></tr><tr><td>plain loop</td><td>10⁸ iterations</td><td>ALU, the loop body</td><td>one loop iteration, 10⁸ in total</td></tr><tr><td>hashmap</td><td>10⁶ inserts + 10⁶ lookups</td><td>hashing, pointer chasing</td><td>one insert or one lookup, 2×10⁶ in total</td></tr></tbody></table><p class="note">The operation count of the sieve is not n. What actually runs is the number of marks in the inner loop, counted as 11,192,870. All languages share this denominator.</p><p>After measuring, all three CPython operations land around 10⁷ per second, and dict operations are close to 5×10⁶. So to estimate a time limit for CPython, 10⁷ is more accurate than 10⁸.</p><h3>When the 9 languages compile, and who manages memory</h3><table><tbody><tr><td></td><td><b>When it becomes machine code</b></td><td><b>Who manages memory</b></td></tr><tr><td>C++, Rust</td><td>Compiled before it runs (AOT, Ahead Of Time)</td><td>The program itself; a variable is freed when it leaves scope</td></tr><tr><td>Go</td><td>Compiled before it runs</td><td>GC (Garbage Collector)</td></tr><tr><td>Java</td><td>Compiled to bytecode first, then the JIT (Just In Time) compiles it to machine code at run time</td><td>GC</td></tr><tr><td>Node, Bun</td><td>Compiled only at run time, JIT. Node uses V8, Bun uses JavaScriptCore</td><td>GC</td></tr><tr><td>PyPy</td><td>Compiled only at run time, JIT</td><td>GC</td></tr><tr><td>CPython, Ruby</td><td>Compiled to bytecode, then interpreted one instruction at a time, no JIT</td><td>GC</td></tr></tbody></table><p>AOT languages run at full speed from round 1. JIT languages need a few rounds before they are compiled to their best (group 4 measures Java: from 68ms down to 37ms). Interpreters are equally slow in every round. C++ manages its own memory. It frees the 1 million hashmap nodes one by one inside the timed region, which costs an extra 15.7ms (group 6).</p><p><b>PyPy and CPython are 2 implementations of the same language.</b> The same <code>.py</code> file runs on both. CPython is the official one. It compiles the code to bytecode and executes it one instruction at a time. PyPy adds a JIT: a loop that runs many times gets compiled to machine code. On the plain loop PyPy is 85x faster, on the sieve 6.2x, on hashmap only 3.6x.</p><table><tbody><tr><td></td><td><b>sieve</b><br>array writes</td><td><b>plain loop</b><br>ALU</td><td><b>hashmap</b><br>hash lookup</td></tr><tr><td>C++ (clang -O2)</td><td>9.55x</td><td>46.4x <i>SIMD</i></td><td>0.26x <i>free</i></td></tr><tr><td>Rust (rustc -O)</td><td>9.6x</td><td>45.1x <i>SIMD</i></td><td>0.34x</td></tr><tr><td>Go</td><td>11.8x</td><td>15.7x</td><td>0.2x</td></tr><tr><td>Java 17</td><td>8.52x</td><td>26.8x</td><td>0.13x</td></tr><tr><td>Bun 1.3</td><td>3.78x</td><td>12.0x</td><td>0.09x</td></tr><tr><td>PyPy 3.11</td><td>1.39x</td><td>11.2x</td><td>0.18x</td></tr><tr><td>Node 22</td><td>2.84x</td><td>10.2x</td><td>0.05x</td></tr><tr><td>Ruby 4.0</td><td>0.2x</td><td>0.2x</td><td>0.06x</td></tr><tr><td>CPython 3.14</td><td>0.22x</td><td>0.13x</td><td>0.05x</td></tr></tbody></table><p class="note"><i>SIMD</i> (Single Instruction Multiple Data) means the compiler rewrote the inner loop so that one instruction computes 8 items at once, so "one operation" in these two C++ and Rust numbers does not mean the same as one item at a time in the other languages. <i>free</i> means C++ has to return the memory the hashmap holds inside the timed region, and this step is expensive: the 1 million entries of <code>unordered_map</code> are 1 million separately allocated nodes, so freeing them calls <code>free</code> 1 million times and costs 15.7ms (group 6). Rust also frees at the same point, but its <code>HashMap</code> is one contiguous allocation, returned in one call. It measures as 0, so the Rust number needs no mark. With that subtracted, C++ on hashmap is <b>0.33x</b>, almost the same as the 0.34x of Rust. This 0.33x is converted from 76.89ms minus 15.7ms.</p><h3>Why the 3 numbers of one language differ so much</h3><p><b>The same 9 languages differ by 119x on the plain loop, and only 6.8x on hashmap.</b> In the plain loop column, among the languages without SIMD, the fastest is Go at 1.57 billion per second and the slowest is CPython at 13.21 million. In the hashmap column, the fastest Rust and the slowest CPython differ by only 6.8x. So if a problem spends its time on hashmap access, rewriting CPython into C++ only gets about 5x faster; if the same problem spends its time in a loop of plain arithmetic, rewriting into Go gets 119x faster.</p><p class="caveat">That 6.8x holds only for the workload in the hashmap column, and that workload is 1 million inserts plus 1 million lookups, half each. Inserting allocates 1 million nodes. This step is especially expensive for C++ (its hashmap costs 38.4ns per operation, lookup only 9.0ns, 4.3x), and almost no burden for CPython (197.5ns against 243.3ns, 0.8x). This 4.3x is a rough number: in the main table half the lookups hit and half miss, and a miss is cheaper than a hit, while the lookup only group hits every time, so "one lookup" is not the same thing on the two sides. In other words, a large part of what shrinks the language gap to 6.8x is the insert part. With lookup only instead (2 million lookups in a map of 1 million entries), slowest divided by fastest for the same 9 languages is <b>27.2x</b>, and rewriting CPython into C++ is 27x faster, not 5x. So "switching language does not gain much" holds only for hashmap problems where inserts and lookups are half each.</p><p><b>Within one language, different operations differ just as much.</b> C++ runs the plain loop at 4.64 billion per second, and hashmap at only 26.01 million, a gap of 178x. So "C++ does 10⁹ per second" holds only for CPU bound loops whose data sits in contiguous memory. Use it to estimate a hashmap heavy solution and you are off by this 178x.</p><p><b>C++ on hashmap costs 30.6ns per operation, and 7.44ns of that depends on whether the data fits in cache.</b> (30.6ns is converted after subtracting the 15.7ms of freeing; see group 6 for the reason.) The reference is one step of the plain loop in the same C++, 0.22ns. The 7.44ns is measured: one C++ lookup in a map of 1000 entries takes 1.51ns, and in a map of 1 million entries 8.95ns. Only the map size changed. To see how long memory takes, pointer chasing measured how long this machine waits to read one value (each array element stores the position of the next element, so where to read next is known only after this read returns, and the CPU cannot overlap the waits):</p><table><tbody><tr><td><b>Total data</b></td><td><b>Wait per read</b></td><td></td></tr><tr><td>16 KB</td><td>1.25 ns</td><td>in L1 (L1d 128KB)</td></tr><tr><td>256 KB</td><td>3.72 ns</td><td>does not fit L1, falls to L2 (12MB)</td></tr><tr><td>4 MB</td><td>6.69 ns</td><td></td></tr><tr><td>32 MB</td><td>89.59 ns</td><td>main memory</td></tr><tr><td>128 MB</td><td>123.60 ns</td><td></td></tr></tbody></table><p class="caveat">This table measures the latency of "waiting for one at a time", because pointer chasing lets the CPU issue only one read at a time. Real programs are mostly not like this: if the addresses can be computed ahead, the CPU can issue several reads at once and the waits overlap. Same 64MB block, same set of random addresses, only remove "the next address has to wait for this read to return", and one read drops from 120ns to 4ns, 30x. So what this table measures is the latency along one dependent chain, and the time actually spread over each read is less than this.</p><p>The CPU moves 128 bytes at a time (<code>sysctl hw.cachelinesize</code>), not just the 8 bytes the program asked for. The inner loop of the sieve walks forward, so it really waits only once every 128 bytes. And its addresses follow a pattern, +i each time. The CPU has a circuit called the prefetcher that looks for exactly this kind of pattern. Once found, it moves the next block into cache ahead of time, and even that one wait is saved.</p><p>Hashmap addresses are neither contiguous nor patterned, so neither the 128 byte move nor the prefetcher helps. The bucket address comes out of the hash: this read goes to bucket 3, the next to bucket 900,000. The 128 bytes moved in last time do not hold the data needed next time, and the prefetcher finds no pattern. And the address is known only after the hash is computed, and whether the stored key is the one wanted is known only after that bucket is read back. This chain can only go one step at a time.</p><p>But lookups are independent of each other, and the CPU can issue several at once. So when the map grows, the extra cost per lookup is not that 90ns, it is the 7.44ns above. That order of magnitude is close to the 4ns of independent access, and more than ten times away from the 120ns of the dependent chain. (An <code>unordered_map</code> of 1 million entries actually takes 56.1MB, measured as resident memory, 58.8 bytes per entry, because each entry is a separately allocated node plus an array of 1,646,237 buckets.)</p><p><b>10⁸ overestimates CPython by 4 to 20x.</b> The 3 CPython numbers are 0.22, 0.13 and 0.05, all below 1. 0.05 is dict: 2×10⁶ operations take 0.39 seconds. A problem that needs 10⁷ dict operations costs CPython 2 seconds. So when estimating CPython, the right baseline is around 10⁷ per second, with dict operations a bit slower, close to 5×10⁶. Not 10⁸.</p><h3>How it was measured</h3><p>One language with one workload is one group. Each group starts 7 independent processes, each process runs 5 times, so that is 35 timings. The 1st run of each process is discarded as warmup, and the median comes from the remaining 28. The <code>±</code> next to the median is the <b>IQR (Interquartile Range)</b>: sort the 28 times from small to large, cut the smallest quarter and the largest quarter, and see how wide the middle half is. It shows whether that group is stable. Java on the plain loop is 37.26ms ± 14.59, so the middle half of the samples spreads over a range wider than 40% of the median; C++ on the plain loop is 21.56ms ± 0.84, the middle half almost stacked on top of each other. IQR instead of standard deviation, because an outlier from one GC or one system scheduling event inflates the standard deviation, while IQR ignores the two ends. The run order of the 203 processes is randomized (fixed seed). A machine that runs continuously heats up and lowers its clock; without randomization that effect always lands on the language that runs last. Every language prints the answer it computed when done (the sieve prints the prime count 348513, the plain loop the sum, hashmap the map size plus the sum of hit values). If any one of the 9 printed answers differs from the others, some implementation is wrong, and that group is discarded and rewritten. The same target runs once at the start and once at the end of the whole round as a drift reference. The end is 1.3% faster than the start, so a gap under 5% cannot be read from this round.</p>`},charts:[{num:`1`,subtitle:{zh:`3 種工作的實測 ops/sec（log 尺度）`,en:`Measured ops/sec of the 3 workloads (log scale)`},description:{zh:`橫軸是每秒操作數，log 尺度。用 log 是因為最快的 C++ 每秒 46.4 億次、最慢的 CPython 506 萬次，中間差 900 倍，線性軸會把下面 6 個語言全部擠成貼著左邊的一條線。深色那條格線標的是 10⁸，USACO Guide 那條線的位置。長條超過那條線，代表那個語言一秒做得完 10⁸ 次；沒超過就是做不完，會超時。`,en:`The horizontal axis is operations per second, log scale. Log because the fastest, C++, does 4.64 billion per second and the slowest, CPython, 5.06 million, a gap of 900x; a linear axis would squeeze the bottom 6 languages into one line stuck to the left edge. The dark grid line marks 10⁸, the position of the USACO Guide line. A bar past that line means the language finishes 10⁸ operations in one second; a bar short of it means it does not, and times out.`},lang:`raw`,codeLabel:{zh:`3 種工作的本體`,en:`The 3 workloads`},sql:`\`\`\`js
// Sieve, n = 5e6. Measures random array writes.
function sieve() {
    composite = byte array of length n+1
    for i = 2..n:
        if not composite[i]:
            count++
            for j = i*i; j <= n; j += i: composite[j] = 1
    return count            // 348513, all 9 languages agree
}

// Plain loop, 10^8 iterations. Measures the ALU and the loop body.
function loopWork() {
    acc = 0
    for i = 0..99,999,999:
        acc += (i ^ (i >> 3)) & 1023
    return acc
}
// Why not acc += i: that has a closed form (Gauss), and clang -O2 folds the whole loop into one constant.
// Why & 1023: keeps the sum under 2^53, otherwise the JS double loses precision
//              and the sum JS prints differs from the other languages by a few digits.

// hashmap: 1e6 inserts + 1e6 lookups, half hit, half miss.
function hashWork() {
    for i = 0..999,999:  map[(i * 2654435761) mod 2^32] = i
    for i = 0..999,999:  k = ((i + 500000) * 2654435761) mod 2^32
                         if k in map: sum += map[k]
    return map.size + sum
}
// The key uses an odd multiplier mod 2^32, which is one to one, so the 1e6 keys are guaranteed distinct.
\`\`\`

Every workload is wrapped in a function and called once per round. Laid out in main or at the top level,
the JIT can only compile through OSR; Java on the plain loop gets 5.7x slower and CPython 1.5x,
and the whole set of numbers is unusable. Details in chart 5.`,chart:{type:`bar`,data:{labels:[`C++`,`Rust`,`Java`,`Go`,`Bun`,`PyPy`,`Node`,`Ruby`,`CPython`],datasets:[e({zh:`純迴圈`,en:`plain loop`},[4638936066,4510006509,2683594206,1569256187,1196340094,1124138629,1019003571,19756655,13213948],t.wlLoop),e({zh:`埃氏篩`,en:`sieve`},[954675135,960241071,851959751,1175469567,377617905,139381840,283739422,19838057,22493449],t.wlSieve),e(`hashmap`,[26011692,34207684,12638330,20011498,8936119,18010882,5305283,5765816,5064279],t.wlHash)]},options:b()},conclusion:{zh:`<p>紫色（hashmap）9 個語言擠在一起，橘色（純迴圈）拉得很開。同一個 C++，橘色跟紫色差 178 倍，比它跟其他任何語言的同色長條差得都多。</p><p>Ruby 是唯一 3 條都短的：0.2x、0.2x、0.06x。它沒有預設開啟的 JIT，所以 3 種工作都用直譯執行。其他 8 個語言裡有 7 個至少有一個數字超過 10x，只有 CPython 三個數字全部低於 1。</p><p class="caveat">C++ 跟 Rust 的橘色含 SIMD。反組譯確認過內迴圈被編譯成 NEON（ARM 的 SIMD 指令集）的 <code>.2d</code>，一個向量 2 個 int64 再展開 4 份，等於一次前進 8 個。工作沒被刪掉（答案有印出來被消費），但那個 46.4 倍是「一次做 8 個」的 46.4 倍。Go 編譯器不做自動向量化，所以 Go 的 15.7 倍是純量的。要拿編譯語言跟直譯語言比純迴圈，用 Go 那條才對等。</p>`,en:`<p>In purple (hashmap) the 9 languages crowd together; in orange (plain loop) they spread far apart. For the same C++, orange and purple differ by 178x, more than it differs from any other language's bar of the same color.</p><p>Ruby is the only one with all 3 bars short: 0.2x, 0.2x, 0.06x. It has no JIT enabled by default, so all 3 workloads run interpreted. Of the other 8 languages, 7 have at least one number above 10x; only CPython has all three numbers below 1.</p><p class="caveat">The orange bars of C++ and Rust include SIMD. Disassembly confirmed the inner loop was compiled to NEON (the ARM SIMD instruction set) <code>.2d</code>: 2 int64 per vector, unrolled 4 times, so each step advances 8. The work was not removed (the answer is printed and consumed), but that 46.4x is the 46.4x of "8 at a time". The Go compiler does no auto vectorization, so the 15.7x of Go is scalar. To compare a compiled language against an interpreted one on the plain loop, the Go bar is the fair one.</p>`}},{num:`2`,subtitle:{zh:`埃氏篩：同一個語言換個寫法，快 2.3 倍`,en:`Sieve: same language, different code, 2.3x faster`},description:{zh:`同一個埃氏篩，Node 用一般 Array 對上 Uint8Array，CPython 用 for 迴圈一次寫一個元素對上 slice assignment 一行寫一整排。2 組都是同一個 runtime、同一個演算法，只換寫法。`,en:`The same sieve. Node with a plain Array against Uint8Array; CPython with a for loop writing one element at a time against slice assignment writing a whole row in one line. Both pairs are the same runtime and the same algorithm, only the code changes.`},lang:`raw`,codeLabel:{zh:`2 組對照的寫法`,en:`The 2 pairs compared`},sql:`\`\`\`js
// Node: plain Array (used in the main table)
const composite = new Array(N + 1).fill(false);
for (let j = i * i; j <= N; j += i) composite[j] = true;

// Node: Uint8Array (the comparison)
const composite = new Uint8Array(N + 1);
for (let j = i * i; j <= N; j += i) composite[j] = 1;
\`\`\`

\`\`\`python
# CPython: for loop, one element at a time (used in the main table, equivalent to the other languages)
for j in range(i * i, N + 1, i):
    composite[j] = True

# CPython: slice assignment (the comparison, the idiomatic way in the Python community)
span = len(range(i * i, N + 1, i))
composite[i * i :: i] = [True] * span
# This line pushes the inner loop into the C layer, which is not what the other languages do, so it is reported separately and not in the main table.
\`\`\``,chart:{type:`bar`,data:{labels:[[`Node`,{zh:`一般 Array`,en:`plain Array`}],[`Node`,`Uint8Array`],[`Bun`,{zh:`一般 Array`,en:`plain Array`}],[`Bun`,`Uint8Array`],[`CPython`,{zh:`for 迴圈`,en:`for loop`}],[`CPython`,`slice`]],datasets:[e({zh:`中位數`,en:`Median`},[39.45,16.9,29.64,12.03,497.61,216.92],t.wlSieve)]},options:s(`ms`)},conclusion:{zh:`<p>Node 從 39.45ms 到 16.90ms，2.3 倍。<code>new Array(N+1).fill(false)</code> 的每個元素是一個能放任何 JS 值的槽位，整個陣列量出來 38.2MB；<code>Uint8Array</code> 的每個元素就是一個 byte，4.8MB。只換這個型別，Node 就比 Bun 的 29.64ms 還快。</p><p>埃氏篩的程式分兩段：先開一個有 n+1 個元素的陣列（<b>配置</b>），再跑迴圈把合數一個一個標起來（<b>標記</b>）。把這兩段分開計時，再拉一個 <code>Float64Array</code> 進來比（跟 Array 一樣每個元素 8 bytes，但不是 JS 的萬用值）。一個 process 只跑一種型別，每種型別 5 個 process、每個 process 跑 15 輪。</p><p><b>這張表怎麼讀</b>：配置跟標記那兩欄，每一欄裡都是三個數字用斜線分開，依序是一般 Array、Float64Array、Uint8Array。所以配置那欄的 <code>0.25 / 0.07 / 0.01</code> 讀作：一般 Array 開這個陣列花 0.25 毫秒、Float64Array 花 0.07、Uint8Array 花 0.01。最後兩欄只看標記那一段，算的是一般 Array 的時間除以另一種型別的時間，也就是換掉型別之後標記快了幾倍。</p><table><tbody><tr><td><b>n</b></td><td><b>配置 ms<br>Array / F64 / U8</b></td><td><b>標記 ms<br>Array / F64 / U8</b></td><td><b>標記<br>Array ÷ U8</b></td><td><b>標記<br>Array ÷ F64</b></td></tr><tr><td>10 萬</td><td>0.25 / 0.07 / 0.01</td><td>0.31 / 0.30 / 0.26</td><td>1.19x</td><td>1.01x</td></tr><tr><td>100 萬</td><td>1.84 / 0.70 / 0.09</td><td>4.00 / 3.32 / 2.88</td><td>1.39x</td><td>1.20x</td></tr><tr><td>200 萬</td><td>3.82 / 1.33 / 0.17</td><td>8.86 / 7.51 / 5.80</td><td>1.53x</td><td>1.18x</td></tr><tr><td>500 萬</td><td>10.80 / 3.91 / 0.43</td><td>30.15 / 28.43 / 14.63</td><td>2.06x</td><td>1.06x</td></tr></tbody></table><p><b>配置。</b><code>new Array(N+1).fill(false)</code> 要把每個元素寫過一遍，n = 500 萬是寫 38MB，花 10.80ms。<code>new Uint8Array(N+1)</code> 拿到的是作業系統的零頁，一個 byte 都不用碰，0.43ms。這一段跟迴圈快不快無關，是配置本身。</p><p><b>元素幾個 byte。</b>看標記那一段的「Array ÷ U8」，從 n = 10 萬的 1.19 倍長到 500 萬的 2.06 倍。它隨資料量走，符合快取的解釋：Array 的 38MB 裝不進 12MB 的 L2（<code>sysctl hw.perflevel0.l2cachesize</code>），Uint8Array 的 4.8MB 裝得下。不過 100 萬筆時 Array 大約 8MB，還裝得進 L2，比值卻已經是 1.39 倍。</p><p><b>萬用值本身。</b>「Array ÷ F64」是 1.01 到 1.20，幾乎沒有。同樣 8 bytes，存純數字跟存「可以放任何 JS 值」的槽位，在這個標記迴圈上分不太出來。</p><p class="caveat">這張表改過兩次，兩次都是我自己在量測程式裡多塞了一個沒控制的變因。第 1 版在同一個 process 裡先量 Array 再量 Uint8Array，V8 看到同一個函式收到兩種元素型別就不再為它專門化，量到的比值被壓縮而且重現不出來。第 2 版把配置算在計時裡面，那段成本被我讀成「萬用值的成本」，所以上一版寫的「1.4 倍來自萬用值、跟快取無關」是錯的，反了。</p><p>Bun 從 29.64ms 到 12.03ms，2.5 倍，跟 Node 的 2.3 倍差不多。所以最快的組合還是 Bun 配 Uint8Array，換 runtime 有它的效果。只是換型別就是改一行 code，部署不用動；換 runtime 要換掉整個執行環境，相依套件全部重測一次。</p><p class="caveat">那 12MB 是 4 個 performance core 共用的（<code>hw.perflevel0.cpusperl2 = 4</code>），不是這支 process 獨佔。量的時候背景程式關掉、其他核心閒著，所以那 4.8MB 幾乎不會被換出去。換一台 4 個核心都在忙的機器，Uint8Array 有一部分會被換出去，倍數會下降，但不會降到 1：配置那一段（10.80ms 對 0.43ms）不管快取怎樣都在。這一句沒有實際在忙碌的機器上量過。</p><p>CPython 從 497.61ms 到 216.92ms，2.3 倍。但這 2.3 倍跟上面那 2.3 倍不是同一回事。篩法的內迴圈要把 i 的倍數一個一個標掉，其他 8 個語言都是跑一步標一個、跑滿 N 步；slice assignment 是把整段範圍一次交給 C 寫的實作，Python 只發一次指令。拿它跟其他語言比，等於比「跑一個 N 步的迴圈」對「呼叫一次 C 函式」。所以主表用 for 迴圈那版。</p>`,en:`<p>Node goes from 39.45ms to 16.90ms, 2.3x. Each element of <code>new Array(N+1).fill(false)</code> is a slot that can hold any JS value; the whole array measures 38.2MB. Each element of <code>Uint8Array</code> is one byte, 4.8MB. Change only this type and Node is already faster than the 29.64ms of Bun.</p><p>The sieve program has two parts: first create an array of n+1 elements (<b>allocate</b>), then run the loop that marks the composites one by one (<b>mark</b>). Time the two parts separately, and bring in a <code>Float64Array</code> for comparison (8 bytes per element like Array, but not a generic JS value). One process runs only one type, 5 processes per type, 15 rounds per process.</p><p><b>How to read this table</b>: in the allocate and mark columns, each cell has three numbers separated by slashes, in the order plain Array, Float64Array, Uint8Array. So <code>0.25 / 0.07 / 0.01</code> in the allocate column reads: a plain Array takes 0.25 milliseconds to create this array, Float64Array 0.07, Uint8Array 0.01. The last two columns look at the mark part only. They divide the plain Array time by the other type's time, that is, how many times faster marking gets after switching the type.</p><table><tbody><tr><td><b>n</b></td><td><b>allocate ms<br>Array / F64 / U8</b></td><td><b>mark ms<br>Array / F64 / U8</b></td><td><b>mark<br>Array \xF7 U8</b></td><td><b>mark<br>Array \xF7 F64</b></td></tr><tr><td>100K</td><td>0.25 / 0.07 / 0.01</td><td>0.31 / 0.30 / 0.26</td><td>1.19x</td><td>1.01x</td></tr><tr><td>1M</td><td>1.84 / 0.70 / 0.09</td><td>4.00 / 3.32 / 2.88</td><td>1.39x</td><td>1.20x</td></tr><tr><td>2M</td><td>3.82 / 1.33 / 0.17</td><td>8.86 / 7.51 / 5.80</td><td>1.53x</td><td>1.18x</td></tr><tr><td>5M</td><td>10.80 / 3.91 / 0.43</td><td>30.15 / 28.43 / 14.63</td><td>2.06x</td><td>1.06x</td></tr></tbody></table><p><b>Allocate.</b> <code>new Array(N+1).fill(false)</code> has to write every element once; at n = 5 million that is writing 38MB, 10.80ms. <code>new Uint8Array(N+1)</code> gets zero pages from the operating system and touches not a single byte, 0.43ms. This part has nothing to do with loop speed; it is the allocation itself.</p><p><b>Bytes per element.</b> Look at "Array \xF7 U8" in the mark part: it grows from 1.19x at n = 100K to 2.06x at 5 million. It follows the data size, which fits the cache explanation: the 38MB of Array does not fit in the 12MB L2 (<code>sysctl hw.perflevel0.l2cachesize</code>), the 4.8MB of Uint8Array does. But at 1 million, Array is about 8MB and still fits in L2, and yet the ratio is already 1.39x.</p><p><b>The generic value itself.</b> "Array \xF7 F64" is 1.01 to 1.20, almost nothing. Same 8 bytes, storing a plain number against a slot that "can hold any JS value": this mark loop can hardly tell them apart.</p><p class="caveat">This table was revised twice, both times because I put an uncontrolled variable into the measuring program myself. Version 1 measured Array and then Uint8Array in the same process. V8 saw the same function receive two element types and stopped specializing for it; the measured ratio was compressed and could not be reproduced. Version 2 counted the allocation inside the timing, and I read that cost as "the cost of the generic value", so what the previous version said, "the 1.4x comes from the generic value, not from cache", was wrong, backwards.</p><p>Bun goes from 29.64ms to 12.03ms, 2.5x, about the same as the 2.3x of Node. So the fastest combination is still Bun with Uint8Array; switching runtime has its own effect. But switching the type is a one line code change with no deployment change; switching runtime replaces the whole execution environment, and every dependency has to be retested.</p><p class="caveat">That 12MB is shared by 4 performance cores (<code>hw.perflevel0.cpusperl2 = 4</code>), not owned by this process alone. During measurement background programs were closed and the other cores idle, so that 4.8MB is almost never evicted. On a machine where all 4 cores are busy, part of the Uint8Array gets evicted and the ratio drops, but not to 1: the allocate part (10.80ms against 0.43ms) is there whatever the cache does. This sentence was not actually measured on a busy machine.</p><p>CPython goes from 497.61ms to 216.92ms, 2.3x. But this 2.3x is not the same thing as the 2.3x above. The inner loop of the sieve marks the multiples of i one by one. The other 8 languages all take one step per mark and run the full N steps; slice assignment hands the whole range to an implementation written in C in one go, and Python issues only one instruction. Comparing it with the other languages is comparing "run a loop of N steps" against "call a C function once". So the main table uses the for loop version.</p>`}},{num:`3`,subtitle:{zh:`Hashmap：9 個語言全在 10⁸ 線下，最快到最慢只差 6.8 倍`,en:`Hashmap: all 9 languages below the 10⁸ line, fastest to slowest only 6.8x apart`},description:{zh:`同一組 hashmap 的數字，換算成對 10⁸ 的倍數。深色那條格線是 1.0，也就是 USACO Guide 那條線本身：低於它代表照 10⁸ 估會超時。9 條全部在線下面。`,en:`The same hashmap numbers, converted to multiples of 10⁸. The dark grid line is 1.0, the USACO Guide line itself: below it means an estimate based on 10⁸ times out. All 9 bars are below the line.`},lang:`raw`,codeLabel:{zh:`各語言用的 map 型別`,en:`The map type each language uses`},sql:"| Language | Type used | What cost this default carries |\n|---|---|---|\n| C++ | `std::unordered_map<uint64_t, int64_t>` | Non cryptographic hash, the cheapest |\n| Rust | `std::collections::HashMap` | SipHash by default, to resist hash collision attacks, slower than the C++ hash |\n| Go | `map[uint64]int64` | Randomized seed, also against collisions |\n| Node / Bun | `Map` | A plain object cannot be used, object keys are converted to strings |\n| CPython | `dict` | Key and value are both objects, every access goes through one more pointer |\n| PyPy | `dict` | Same as above, but the JIT compiles the hot path to machine code |\n| Java | `HashMap<Long, Long>` | Generics cannot take primitive types, every put and get boxes into an object |\n| Ruby | `Hash` | Same as CPython, all objects |\n\nAll 9 use the default of each language, because that is the type you get when typing out a solution.\nSo this group measures not only the hashing itself, but also what each language's default decided for the programmer.",chart:{type:`bar`,data:{labels:[`Rust`,`C++`,`Go`,`PyPy`,`Java`,`Bun`,`Ruby`,`Node`,`CPython`],datasets:[e({zh:`對 10⁸ 的倍數`,en:`multiple of 10⁸`},[.34,.26,.2,.18,.13,.09,.06,.05,.05],t.wlHash)]},options:m(`x`,1,1.1)},conclusion:{zh:`<p>最快的 Rust 是 0.34x，代表照 10⁸ 估出來的時間，實際要花 3 倍。C++ 0.26x 是 4 倍，CPython 跟 Node 的 0.05x 是 20 倍。一題如果 hashmap 存取次數是主要成本，不管用什麼語言，10⁸ 估出來的時間都要再乘 3 到 20。</p><p>語言之間的差異也很小，尤其是跟埃氏篩、純迴圈比。這一欄最快的 Rust 每秒 3421 萬次，最慢的 CPython 506 萬次，只差 6.8 倍。同樣這 9 個語言跑埃氏篩最快到最慢差 59 倍，跑純迴圈差 119 倍。所以 hashmap 吃重的題目，換語言也快不了多少。</p><p>不過這句話只在 hashmap 這一欄的工作內容上成立，而它的內容是插入 100 萬次加查詢 100 萬次，各佔一半。把插入拿掉只留查詢，同樣 9 個語言差 27.2 倍。三個跨度排在一起：</p><table><tbody><tr><td>埃氏篩</td><td>59.3 倍</td><td></td></tr><tr><td>hashmap 純查詢</td><td>27.2 倍</td><td>比埃氏篩少的部分來自位址亂跳</td></tr><tr><td>hashmap 插入 + 查詢各半</td><td>6.8 倍</td><td>比純查詢少的部分來自配置</td></tr></tbody></table><p><b>27.2 降到 6.8，是因為工作內容從全部是查詢，換成一半查詢一半插入。</b>插入 100 萬筆要配置 100 萬個節點，那對 C++ 很貴（hashmap 每次操作 38.4ns，純查詢只要 9.0ns），對 CPython 幾乎沒有負擔（197.5ns 對 243.3ns，它的查詢比平均一次操作還貴）。快的語言被配置拖住，慢的本來就慢，差距就縮了。</p><p>59.3 降到 27.2 那一段是另一回事：埃氏篩讀記憶體是一個元素接一個元素，CPU 猜得到下一個在哪、先把資料搬過來；hashmap 查詢的位址亂跳，猜不到，每次都要等記憶體，只是幾次查詢的等待可以互相重疊。而等的時間跟語言無關，等的比例愈高，語言之間的差距就愈小。第 8 組另外寫了一支程式來單獨測這件事，那支沒有 hashmap，只有一個陣列跟一個迴圈。同一個陣列、同一個迴圈，只把讀取順序從連續換成亂跳，9 個語言之間最慢跟最快的差距，就從 90.6 倍縮小到 47.1 倍。</p><p class="caveat">那是類比，不是 hashmap 本身。</p>`,en:`<p>The fastest, Rust, is 0.34x, meaning the time estimated with 10⁸ actually takes 3 times as long. C++ at 0.26x is 4 times, CPython and Node at 0.05x are 20 times. If hashmap accesses are the main cost of a problem, whatever the language, the time estimated with 10⁸ has to be multiplied by 3 to 20.</p><p>The difference between languages is also small, especially compared with the sieve and the plain loop. In this column the fastest, Rust, does 34.21 million per second and the slowest, CPython, 5.06 million, only 6.8x apart. The same 9 languages differ by 59x from fastest to slowest on the sieve, and 119x on the plain loop. So on a hashmap heavy problem, switching language does not gain much.</p><p>But that sentence holds only for the workload in the hashmap column, and that workload is 1 million inserts plus 1 million lookups, half each. Remove the inserts and keep only lookups, and the same 9 languages differ by 27.2x. The three spans side by side:</p><table><tbody><tr><td>sieve</td><td>59.3x</td><td></td></tr><tr><td>hashmap, lookup only</td><td>27.2x</td><td>the drop from the sieve comes from scattered addresses</td></tr><tr><td>hashmap, half insert + half lookup</td><td>6.8x</td><td>the drop from lookup only comes from allocation</td></tr></tbody></table><p><b>27.2 drops to 6.8 because the workload changes from all lookups to half lookups and half inserts.</b> Inserting 1 million entries allocates 1 million nodes. That is expensive for C++ (38.4ns per hashmap operation, lookup only 9.0ns), and almost no burden for CPython (197.5ns against 243.3ns; its lookup costs more than its average operation). The fast languages get held back by allocation, the slow ones were slow already, so the gap shrinks.</p><p>The drop from 59.3 to 27.2 is a different matter: the sieve reads memory one element after another, so the CPU can guess where the next one is and move the data in ahead of time; hashmap lookups jump to scattered addresses, which cannot be guessed, so every one waits for memory, except that the waits of several lookups can overlap. And the waiting time has nothing to do with the language. The larger the share of waiting, the smaller the gap between languages. Group 8 wrote a separate program to test exactly this. It has no hashmap, only one array and one loop. Same array, same loop, only the read order changes from sequential to scattered, and the gap between the slowest and the fastest of the 9 languages shrinks from 90.6x to 47.1x.</p><p class="caveat">That is an analogy, not the hashmap itself.</p>`}},{num:`4`,subtitle:{zh:`Java 跑到第 3 輪才拿到最快的那份程式碼`,en:`Java only gets its fastest code in round 3`},description:{zh:`同一個 process 內的 5 次迭代，7 個 process 取中位數。前 2 輪跑在還沒優化完的程式碼上，第 3 輪之後才穩定。這張圖畫的是主表純迴圈那一欄底下發生的事。`,en:`5 iterations inside the same process, median over 7 processes. The first 2 rounds run on code that is not yet fully optimized; it stabilizes from round 3. This chart shows what happens underneath the plain loop column of the main table.`},lang:`raw`,codeLabel:{zh:`7 個 process 每一輪的數字（ms）`,en:`Each round of the 7 processes (ms)`},sql:`\`\`\`
         iter0    iter1    iter2    iter3    iter4
proc 1   68.14    63.84    36.41    37.33    36.80
proc 2   68.89    69.88    35.95    35.76    37.04
proc 3   68.99    69.59    37.43    39.52    38.80

The 7 processes produce almost the same numbers; round 3 always drops to about 37ms.
\`\`\``,chart:{type:`bar`,data:{labels:[{zh:`第 1 輪`,en:`round 1`},{zh:`第 2 輪`,en:`round 2`},{zh:`第 3 輪`,en:`round 3`},{zh:`第 4 輪`,en:`round 4`},{zh:`第 5 輪`,en:`round 5`}],datasets:[e({zh:`Java 跑純迴圈（中位數）`,en:`Java plain loop (median)`},[68.14,65.24,37.2,37,37.17],t.wlLoop)]},options:s(`ms`)},conclusion:{zh:`<p>第 1 輪 68ms，第 2 輪 65ms，第 3 輪降到 37ms 就不再動。前 2 輪跑的是還沒完全優化的程式碼。</p><p>編譯本身只花 10 到 14ms（<code>java -XX:+CITime</code> 印的），可是前 2 輪比穩定狀態多花了 59ms。多出來的大部分不在編譯本身，比較可能花在跑還沒編譯好的那份程式碼上。改用 <code>-Xbatch</code> 讓編譯停下程式來做，第 1 輪還是 66ms，跟預設的 68ms 一樣。</p><p>這件事會污染中位數。主表的中位數取第 2 到第 5 輪，所以 28 個樣本裡有 7 個是那個 65ms。中位數本身沒被拉走（37.26ms 對只取第 3 到 5 輪的 37.17ms），但 IQR 算出來是 14.59ms，看起來像 Java 很不穩，其實是 warmup 還沒結束。Bun 跑埃氏篩、Java 跑 hashmap 也有同樣的情形，程度小一些：拿第 2 輪的中位數比第 3 到 5 輪，Bun 的埃氏篩高 23%（35.20ms 對 28.66ms）、Java 的 hashmap 高 17%（179.35ms 對 153.27ms），Java 的純迴圈是 76%（65.24ms 對 37.17ms）。</p><p>線上評測通常只把解法跑一次，而只跑一次就結束的程式，拿到的是 68ms 那份，不是 37ms 那份。</p>`,en:`<p>Round 1 is 68ms, round 2 65ms, round 3 drops to 37ms and stays there. The first 2 rounds run code that is not yet fully optimized.</p><p>Compilation itself takes only 10 to 14ms (printed by <code>java -XX:+CITime</code>), yet the first 2 rounds cost 59ms more than the steady state. Most of the extra is not in the compilation itself; it is more likely spent running the code that is not compiled yet. With <code>-Xbatch</code>, which pauses the program to compile, round 1 is still 66ms, the same as the default 68ms.</p><p>This pollutes the median. The main table median takes rounds 2 to 5, so 7 of the 28 samples are that 65ms. The median itself is not pulled away (37.26ms against 37.17ms with rounds 3 to 5 only), but the IQR comes out at 14.59ms, which looks like Java is unstable, when in fact the warmup is not over. Bun on the sieve and Java on hashmap show the same thing, to a smaller degree: comparing the round 2 median with rounds 3 to 5, the Bun sieve is 23% higher (35.20ms against 28.66ms), the Java hashmap 17% higher (179.35ms against 153.27ms), and the Java plain loop 76% (65.24ms against 37.17ms).</p><p>An online judge usually runs a solution once, and a program that runs once and exits gets the 68ms version, not the 37ms one.</p>`}},{num:`5`,subtitle:{zh:`迴圈攤在 main 裡：Java 慢 5.7 倍，Node 不受影響（這組害我整輪重跑）`,en:`Loop laid out in main: Java 5.7x slower, Node unaffected (this group forced a full rerun)`},description:{zh:`一開始跑的設計，是把 3 種工作的迴圈直接寫在 main 裡、module 的最外層。重跑那次只改了一個地方：把迴圈包進一個函式，每輪呼叫一次。演算法、輸入、答案全部沒動。這張圖是同一次執行裡 2 種寫法背靠背跑出來的比值。`,en:`The first design wrote the loops of the 3 workloads directly in main, at the top level of the module. The rerun changed one thing only: it wrapped the loop in a function, called once per round. Algorithm, input and answer were all untouched. This chart is the ratio of the 2 versions run back to back in the same execution.`},lang:`raw`,codeLabel:{zh:`差在哪一行`,en:`Which line differs`},sql:`\`\`\`java
// At first: the loop laid out in main
public static void main(String[] args) {
    for (int it = 0; it < 5; it++) {
        long t0 = System.nanoTime();
        long acc = 0;
        for (long i = 0; i < N; i++) acc += (i ^ (i >> 3)) & 1023;   // \u2190 here
        ...
    }
}

// The rerun: moved into a method that gets called
static long loopWork() {
    long acc = 0;
    for (long i = 0; i < N; i++) acc += (i ^ (i >> 3)) & 1023;
    return acc;
}
public static void main(String[] args) {
    for (int it = 0; it < 5; it++) {
        long t0 = System.nanoTime();
        long acc = loopWork();                                        // \u2190 changed to this
        ...
    }
}
\`\`\`

Measured (same execution, back to back):

           top level     in function
Java         207 ms       36 ms
PyPy         213 ms       89 ms
CPython    11146 ms     7450 ms
Bun         96.8 ms     81.2 ms
Node        94.9 ms     95.0 ms`,chart:{type:`bar`,data:{labels:[`Java`,`PyPy`,`CPython`,`Bun`,`Node`],datasets:[e({zh:`包進函式之後快幾倍`,en:`speedup inside a function`},[5.7,2.4,1.5,1.2,1],t.neutral)]},options:m(`x`,1)},conclusion:{zh:`<p><b>Java 5.7 倍，PyPy 2.4 倍：JIT 只能走 OSR。</b><code>main</code> 從頭到尾只執行一次，不會有第二次呼叫，所以 JIT 沒有「下次呼叫時換成編譯版」這個機會。它只剩 OSR（On-Stack Replacement）可用，也就是趁迴圈跑到一半，把正在執行的那份程式碼抽換掉。OSR 編譯出來的 machine code 比正常編譯的差。包成函式呼叫 5 次，第 2 次之後就走正常路徑。</p><p><b>CPython 1.5 倍：變數存取的位置不一樣。</b>module 最外層的變數是 global，每次讀寫都要查詢一次 dict；函式裡的是 local，編譯成陣列索引。這是 Python 常見的效能問題，這次出現在 benchmark 程式本身的結構上。</p><p><b>Bun 1.2 倍、Node 1.0 倍：同樣是 JS，引擎不一樣。</b>Bun 跑的是 JavaScriptCore，Node 跑的是 V8。重跑確認過（各 3 個 process、丟掉第 1 輪）：Bun 攤在最外層停在 93.8ms，包進函式跑到 80.2ms；Node 兩種寫法都在 95ms 上下，動都不動。JSC 有 4 級 JIT，由慢到快是 LLInt（Low Level Interpreter）、Baseline、DFG（Data Flow Graph）、FTL（Faster Than Light），程式剛開始跑走最慢那一級，執行次數夠多才換到上一級。編譯記錄（跑的時候帶 <code>BUN_JSC_reportCompileTimes=1</code>）顯示兩種寫法都升到了最快的 FTL，所以不是升不上去。兩種寫法編譯的單位不一樣：包進函式的時候，JSC 編譯的是 <code>loopWork</code> 這 51 個 bytecode，產出 180 到 432 bytes 的 machine code；攤在最外層的時候，它編譯的是整個 module 主體 229 個 bytecode，產出 2484 到 2816 bytes。</p><p>所以那個設計不是讓每個語言都慢一樣多。慢的倍數從 1.0 到 5.7 都有，排名也跟著錯。</p><p class="caveat">一開始那次還報過 3 個「速度一直沒穩定下來」的發現：Java 的純迴圈第 1 輪 66ms 之後 4 輪都是 203ms、PyPy 的埃氏篩在 63 到 126ms 之間來回擺盪、Bun 的純迴圈有 4 成 process 停在 95ms。包進函式之後 3 個全部消失。PyPy 的 IQR 從 38.15ms 降到 7.10ms，Bun 的從 31.57ms 降到 3.47ms。那 3 個現象是我自己的 code 結構造成的，不是 runtime 的行為。</p>`,en:`<p><b>Java 5.7x, PyPy 2.4x: the JIT can only go through OSR.</b> <code>main</code> runs only once from start to end. There is no second call, so the JIT has no chance to "swap in the compiled version on the next call". Only OSR (On-Stack Replacement) is left: replace the code that is running while the loop is halfway through. The machine code OSR produces is worse than a normal compile. Wrapped in a function called 5 times, it takes the normal path from the 2nd call on.</p><p><b>CPython 1.5x: variables live in a different place.</b> Variables at the top level of a module are global, and every read or write looks up a dict; those inside a function are local, compiled to an array index. This is a common Python performance issue, and this time it showed up in the structure of the benchmark program itself.</p><p><b>Bun 1.2x, Node 1.0x: same JS, different engine.</b> Bun runs JavaScriptCore, Node runs V8. A rerun confirmed it (3 processes each, round 1 discarded): Bun at the top level stays at 93.8ms and wrapped in a function reaches 80.2ms; Node is around 95ms either way, not moving at all. JSC has 4 JIT tiers, from slow to fast: LLInt (Low Level Interpreter), Baseline, DFG (Data Flow Graph), FTL (Faster Than Light). A program starts on the slowest tier and moves up a tier only after enough executions. The compile log (run with <code>BUN_JSC_reportCompileTimes=1</code>) shows both versions reached the fastest tier, FTL, so it is not that it failed to move up. The two versions compile a different unit: wrapped in a function, JSC compiles the 51 bytecodes of <code>loopWork</code> and produces 180 to 432 bytes of machine code; at the top level, it compiles the whole module body, 229 bytecodes, and produces 2484 to 2816 bytes.</p><p>So that design did not slow every language by the same amount. The slowdown ranges from 1.0 to 5.7x, and the ranking goes wrong with it.</p><p class="caveat">The first run also reported 3 findings of "speed never stabilizes": the Java plain loop at 66ms in round 1 and then 203ms in all 4 following rounds, the PyPy sieve swinging back and forth between 63 and 126ms, and 40% of the Bun plain loop processes stuck at 95ms. Wrapped in a function, all 3 disappeared. The PyPy IQR dropped from 38.15ms to 7.10ms, the Bun one from 31.57ms to 3.47ms. Those 3 phenomena came from the structure of my own code, not from runtime behavior.</p>`}},{num:`6`,subtitle:{zh:`Hashmap 的測試對追蹤式 GC 的語言有利，C++ 多花 15.7ms`,en:`The hashmap test favors languages with a tracing GC; C++ pays an extra 15.7ms`},description:{zh:`包進函式的時候，hashmap 也跟著在函式回傳前就出了作用域，所以「把 100 萬個節點還給系統」被算進計時裡。這張圖量那段釋放要花多久，順便看哪些語言也在同一個點釋放。`,en:`Once wrapped in a function, the hashmap also leaves scope before the function returns, so "return 1 million nodes to the system" is counted inside the timing. This chart measures how long that freeing takes, and also checks which languages free at the same point.`},lang:`raw`,codeLabel:{zh:`2 種寫法的差別`,en:`The difference between the 2 versions`},sql:`\`\`\`cpp
// Current h.cpp: the map lives inside hashwork()
static int64_t hashwork() {
    std::unordered_map<uint64_t, int64_t> m;
    // fill 1 million, look up 1 million times
    return (int64_t)m.size() + sum;
}                                  // \u2190 m is freed here, before the function even returns
for (int it = 0; it < 5; it++) {
    auto t0 = now();
    int64_t checksum = hashwork();
    auto t1 = now();               // \u2190 timing stops here, the free is already counted
    printf("iter=%d ns=%lld\\n", it, ns_between(t0, t1));
}

// The chart 5 version: the map lives inside one loop iteration
for (int it = 0; it < 5; it++) {
    auto t0 = now();
    std::unordered_map<uint64_t, int64_t> m;
    // fill 1 million, look up 1 million times
    auto t1 = now();               // \u2190 timing stops here
    printf("iter=%d ns=%lld\\n", it, ns_between(t0, t1));
}                                  // \u2190 m is freed only when each iteration reaches here
\`\`\``,chart:{type:`bar`,data:{labels:[[`C++ hashmap`,{zh:`釋放算進計時`,en:`free inside timing`}],[`C++ hashmap`,{zh:`釋放在計時之外`,en:`free outside timing`}]],datasets:[e({zh:`中位數（第 2 到 5 輪）`,en:`Median (rounds 2 to 5)`},[65.07,49.37],t.wlHash)]},options:s(`ms`)},conclusion:{zh:`<p>65.07ms 對 49.37ms，釋放那 100 萬個節點花掉 15.7ms，佔主表 C++ 跑 hashmap 那 76.89ms 的 20%。</p><p>決定保留現在的行為，因為釋放本來就是這個解法的一部分。但它對 C++ 不公平：C++ 在計時區間內逐個節點呼叫 free，其他語言交給 GC。</p><p>其他 GC 語言也要回收這 100 萬筆，但比 C++ 快得多。<b>追蹤（tracing）</b>是從變數出發走訪還活著的物件，走不到的就當成垃圾。<b>引用計數（reference counting）</b>是每個物件記著有幾個參照指向它，數到 0 就當場釋放。</p><table><tbody><tr><td><b>怎麼認垃圾</b></td><td><b>誰用</b></td><td><b>收掉 100 萬筆要多久</b></td></tr><tr><td>追蹤</td><td>Java、Go、JS、Ruby</td><td>Node 0.9ms、Ruby 1.3ms</td></tr><tr><td>引用計數</td><td>CPython</td><td>17.4ms</td></tr></tbody></table><p>追蹤式 GC 走的是還活著的物件，所以死掉的那 100 萬個節點一個都不碰。Ruby 那組看得最清楚：hash 還活著的時候強制回收要 4.9ms，把它變成垃圾之後再收只要 1.3ms。V8 也是同一回事，收掉一個 100 萬筆的 Map 是 0.9ms（回收前 heap 53.1MB、回收後 3.4MB，確認真的收掉了）。</p><p><b>CPython 是例外，它跟 C++ 同一組。</b>引用計數在計數歸零的那一刻就把物件釋放掉，所以 100 萬個 entry 每一個都要個別釋放。<code>del</code> 一個 100 萬筆的 dict 量到 17.4ms，跟 C++ 的 15.7ms 差不多。而且主表那份 CPython 實作，dict 是函式裡的區域變數，函式一回傳計數就歸零，所以 CPython 跟 C++ 一樣，那筆釋放成本被算進計時裡了。不過 C++ 的 15.7ms 佔它 76.89ms 的 20.4%，CPython 的 17.4ms 只佔它 394.92ms 的 4.4%。所以下面只替 C++ 算一個扣掉之後的數字。對 CPython 做同樣的事，0.05x 幾乎不動（377.52ms 換算還是 0.05x），改了也看不出來有差別。</p><p>追蹤式那 4 個語言則是另一回事：GC 什麼時候動手不由程式決定，那 1ms 上下可能落在下一輪的計時裡，也可能不落在任何一輪裡。</p><p>Rust 也是手動管理記憶體，但它幾乎不花時間。同一組對照在 Rust 上跑，計時含釋放 53.45ms、不含 53.59ms，差 −0.14ms，等於零。C++ 標準規定 <code>unordered_map</code> 的元素位址在 rehash 之後仍然有效，所以每一筆是一個獨立配置的節點，釋放時要呼叫 100 萬次 <code>free</code>；Rust 沒有這條規定，它的 <code>HashMap</code> 就把整張表放在一塊連續配置裡。而且這裡存的是 <code>u64</code> 跟 <code>i64</code>，純數字，每一筆自己沒有別的資源要清，所以丟掉整張表就是還一塊記憶體。換成存字串就不是這樣了：每個字串自己在 heap 上有一塊緩衝區，丟掉表的時候要一個一個去還，那就跟 C++ 一樣慢。</p><p>9 個語言的 hashmap 分三種放法：</p><table><tbody><tr><td><b>每一筆放在哪</b></td><td><b>語言</b></td></tr><tr><td>跟表放在同一塊連續記憶體</td><td>Rust、Go</td></tr><tr><td>表是連續的，但每一筆指向另外配置的物件</td><td>CPython、Ruby、JS、PyPy</td></tr><tr><td>每一筆自己一個獨立配置</td><td>C++、Java</td></tr></tbody></table><p>C++ 落在最後一組，所以要跑 100 萬次釋放；Rust 在第一組，還一塊就結束。CPython 是中間那組，表本身連續，但 100 萬個 key 跟 value 各是一個物件，所以它那 17.4ms 比較可能慢在物件，不是慢在表。Java 的配置最多：表存指標、每一筆是一個 Node 物件、<code>Long</code> key 又是一個物件，一筆三層，它的 hashmap 每次操作 79.1ns，在編譯語言裡最慢。</p><p class="caveat">這張分類是各語言標準函式庫的實作方式，不是這輪量出來的；這輪只量了 C++ 跟 Rust 兩個的釋放成本。</p><p>所以主表 Rust 那個 0.34x 不用修正，它根本沒花這個時間。扣掉 15.7ms 換算，C++ 跑 hashmap 是 0.33x（76.89ms 減 15.7ms 得 61.19ms，每秒 3269 萬次），跟 Rust 幾乎並排。</p><p>圖 5 那個把迴圈攤在 main 裡的版本一樣要釋放，只是釋放發生在計時之外（C++ 55.11ms 對現在的 76.89ms）。那版的 map 宣告在 for 迴圈裡面，程式碼順序是「填完、查完、停計時、印出來、跑到迴圈那一圈的收尾大括號才釋放」。同一件工作照做 5 次，只是每次都在計時停掉之後。兩版差的 21.8ms 裡，有 15.7ms 是釋放移出了計時範圍。</p>`,en:`<p>65.07ms against 49.37ms: freeing those 1 million nodes costs 15.7ms, 20% of the 76.89ms of C++ on hashmap in the main table.</p><p>The current behavior stays, because freeing is part of this solution anyway. But it is unfair to C++: C++ calls free node by node inside the timed region, the other languages leave it to the GC.</p><p>The other GC languages also have to reclaim these 1 million entries, but much faster than C++. <b>Tracing</b> starts from the variables and visits the objects still alive; whatever cannot be reached is garbage. <b>Reference counting</b> has each object record how many references point to it, and frees it on the spot when the count reaches 0.</p><table><tbody><tr><td><b>How garbage is found</b></td><td><b>Who uses it</b></td><td><b>Time to reclaim 1 million</b></td></tr><tr><td>tracing</td><td>Java, Go, JS, Ruby</td><td>Node 0.9ms, Ruby 1.3ms</td></tr><tr><td>reference counting</td><td>CPython</td><td>17.4ms</td></tr></tbody></table><p>A tracing GC walks the live objects, so it never touches a single one of the 1 million dead nodes. The Ruby group shows it most clearly: a forced collection while the hash is still alive takes 4.9ms, collecting after it has become garbage only 1.3ms. V8 is the same: reclaiming a Map of 1 million entries is 0.9ms (heap 53.1MB before, 3.4MB after, confirming it was really reclaimed).</p><p><b>CPython is the exception; it belongs with C++.</b> Reference counting frees the object the moment the count reaches zero, so every one of the 1 million entries is freed individually. <code>del</code> on a dict of 1 million entries measures 17.4ms, close to the 15.7ms of C++. And in the CPython implementation of the main table, the dict is a local variable inside the function, so the count reaches zero as soon as the function returns, which means CPython, like C++, has that freeing cost counted inside the timing. But the 15.7ms of C++ is 20.4% of its 76.89ms, while the 17.4ms of CPython is only 4.4% of its 394.92ms. So below, only C++ gets a number with the free subtracted. Doing the same for CPython, 0.05x barely moves (377.52ms still converts to 0.05x), and the change would not be visible.</p><p>The 4 tracing languages are a different matter: the program does not decide when the GC runs, so that 1ms or so may land in the next round's timing, or in no round at all.</p><p>Rust also manages memory manually, but it spends almost no time on it. The same comparison on Rust: timing with the free 53.45ms, without 53.59ms, a difference of \u22120.14ms, which is zero. The C++ standard requires that element addresses in <code>unordered_map</code> stay valid after a rehash, so each entry is a separately allocated node, and freeing calls <code>free</code> 1 million times; Rust has no such rule, and its <code>HashMap</code> puts the whole table in one contiguous allocation. And what is stored here is <code>u64</code> and <code>i64</code>, plain numbers; no entry has other resources of its own to clean up, so dropping the whole table is returning one block of memory. Storing strings would be different: each string has its own buffer on the heap, and dropping the table has to return them one by one, which is as slow as C++.</p><p>The hashmaps of the 9 languages fall into three layouts:</p><table><tbody><tr><td><b>Where each entry lives</b></td><td><b>Languages</b></td></tr><tr><td>In the same contiguous memory as the table</td><td>Rust, Go</td></tr><tr><td>The table is contiguous, but each entry points to a separately allocated object</td><td>CPython, Ruby, JS, PyPy</td></tr><tr><td>Each entry is its own separate allocation</td><td>C++, Java</td></tr></tbody></table><p>C++ is in the last group, so it runs 1 million frees; Rust is in the first, and returning one block is the end of it. CPython is in the middle group: the table itself is contiguous, but the 1 million keys and values are each an object, so its 17.4ms is more likely spent on the objects, not on the table. Java has the most allocations: the table stores pointers, each entry is a Node object, and the <code>Long</code> key is another object, three layers per entry. Its hashmap costs 79.1ns per operation, the slowest among the compiled languages.</p><p class="caveat">This classification is how each language's standard library is implemented, not something this round measured; this round measured the freeing cost of C++ and Rust only.</p><p>So the 0.34x of Rust in the main table needs no correction; it never spent this time at all. Subtracting 15.7ms and converting, C++ on hashmap is 0.33x (76.89ms minus 15.7ms is 61.19ms, 32.69 million per second), almost level with Rust.</p><p>The chart 5 version with the loop laid out in main also has to free, only the free happens outside the timing (C++ 55.11ms against the current 76.89ms). In that version the map is declared inside the for loop, and the code order is "fill, look up, stop the timer, print, and free only when the iteration reaches its closing brace". The same work is done 5 times, just after the timer stops each time. Of the 21.8ms between the two versions, 15.7ms is the free moved out of the timed range.</p>`}},{num:`7`,subtitle:{zh:`啟動成本：還沒開始計算就先花掉的時間`,en:`Startup cost: time spent before any computing starts`},description:{zh:`Ruby 光是啟動就要 35ms，而 Go 跑完整個埃氏篩才 9.52ms。如果限制一定得在 1 秒內跑完，Ruby 有 3.5% 的時間在還沒開始算之前就用掉了。啟動花多久，跟每秒能算幾次是 2 件事，混在同一個數字裡就看不見它，所以分開量。工具用 hyperfine，它專門量指令的執行時間，會把同一條指令重跑很多次再給平均跟標準差。這裡設定跑 30 次、warmup 3 次，量的程式就是下面那個。`,en:`Ruby needs 35ms just to start, while Go finishes the whole sieve in 9.52ms. If the limit is that it must finish within 1 second, Ruby has used up 3.5% of the time before it starts computing. How long startup takes and how many operations per second are 2 different things; mixed into one number, startup becomes invisible, so it is measured separately. The tool is hyperfine, which is built to time commands: it reruns the same command many times and reports the mean and standard deviation. Here it is set to 30 runs and 3 warmups, and the program measured is the one below.`},lang:`raw`,codeLabel:{zh:`量的是什麼`,en:`What is measured`},sql:'```cpp\n// noop.cpp\nint main() { return 0; }\n```\n\n```js\n// noop.js  ← the whole file is this one comment line\n```\n\n```bash\nhyperfine --warmup 3 --runs 30 \\\n  -n cpp "./out/noop-cpp"  -n node "node noop.js"  -n ruby "ruby noop.rb"  ...\n```',chart:{type:`bar`,data:{labels:[`Go`,`C++`,`Rust`,`Bun`,`CPython`,`PyPy`,`Java`,`Node`,`Ruby`],datasets:[e({zh:`啟動時間（平均）`,en:`startup time (mean)`},[2.1,2.4,2.6,11.9,22.1,22.2,27.5,31.4,35.1],t.neutral)]},options:s(`ms`)},conclusion:{zh:`<p>3 個編譯語言都在 2ms 出頭，其他 6 個是 12ms 到 35ms。這一欄跟解法寫得好不好無關，不管演算法多漂亮，這 12 到 35ms 都要先花掉。</p><p>Bun 的 11.9ms 是 Node 的 31.4ms 的 38%。這是 Bun 贏 Node 最多的一項，比它們在 3 種工作上的任何一項都多。對一個本身只跑 20ms 的程式，多這 20ms 就等於總時間翻倍。</p><p class="caveat">這張表量的是檔案已經讀過一次之後的啟動。hyperfine 帶 <code>--warmup 3</code>，那 3 次 warmup 把執行檔跟共用函式庫都讀進檔案系統快取了。</p>`,en:`<p>The 3 compiled languages are all just over 2ms, the other 6 are 12ms to 35ms. This column has nothing to do with how well the solution is written; however elegant the algorithm, these 12 to 35ms are spent first.</p><p>The 11.9ms of Bun is 38% of the 31.4ms of Node. This is where Bun beats Node by the most, more than on any of the 3 workloads. For a program that itself runs only 20ms, these extra 20ms double the total time.</p><p class="caveat">This table measures startup after the files have been read once. hyperfine runs with <code>--warmup 3</code>, and those 3 warmups read the executable and the shared libraries into the file system cache.</p>`}},{num:`8`,subtitle:{zh:`位址亂跳的時候，快的語言變慢的倍數比慢的語言大`,en:`With scattered addresses, fast languages slow down by a larger factor than slow ones`},description:{zh:`第 3 組留了一句猜測：hashmap 讓 9 個語言只差 6.8 倍，是因為時間花在等記憶體，而等記憶體誰來等都一樣慢。這張圖去測那句話，用的是另外寫的一支程式，裡面沒有 hashmap，只有一個陣列跟一個迴圈。一個整數陣列讀 200 萬次，讀哪 200 萬格由外部檔案指定：一份照位址從小到大排，一份是同一批位址洗過牌。兩份讀一樣多次、讀一樣的位址、算出一樣的答案，唯一的差別是先後順序。縱軸是亂序讀比順序讀慢幾倍，三種顏色是陣列開多大。`,en:`Group 3 left a guess: hashmap brings the 9 languages to within 6.8x because the time goes to waiting for memory, and waiting for memory is equally slow whoever waits. This chart tests that sentence with a separately written program that has no hashmap, only one array and one loop. An integer array is read 2 million times, and which 2 million cells to read comes from an external file: one file sorted by address from low to high, one the same set of addresses shuffled. Both read the same number of times, read the same addresses and compute the same answer; the only difference is the order. The vertical axis is how many times slower the scattered read is than the sequential read, and the three colors are the array size.`},lang:`raw`,codeLabel:{zh:`兩個變體差在哪`,en:`Where the two variants differ`},sql:`\`\`\`cpp
// The indices are generated once by a script; the 9 languages read the same binary file, no per language shuffle.
// With per language shuffles the 9 languages would get different addresses, and "the same set of addresses" would no longer hold.
//   idx-seq-<n>.bin  =  0, 4, 8, 12, ...        linear scan of the array
//   idx-rnd-<n>.bin  =  the same numbers, shuffled
static uint64_t read_work(const std::vector<uint64_t> &arr, const std::vector<uint32_t> &idx) {
    uint64_t sum = 0;                                 // \u2190 both variants run this same function
    for (uint64_t p = 0; p < 2000000; p++) sum += arr[idx[p]];
    return sum;
}

int main(int argc, char **argv) {
    // The variant and the array size both come from the command line; one process runs one combination only.
    // Packed into one process, the one that runs first would not get the JIT state accumulated later.
    std::vector<uint32_t> idx = load(argv[1], strtoull(argv[2], nullptr, 10));
    std::vector<uint64_t> arr = build(strtoull(argv[2], nullptr, 10));

    for (int it = 0; it < 15; it++) {
        auto t0 = now();
        uint64_t sum = read_work(arr, idx);
        auto t1 = now();
        printf("variant=%s iter=%d ns=%lld checksum=%llu\\n", argv[1], it, ns_between(t0, t1), sum);
    }
}
\`\`\``,chart:{type:`bar`,data:{labels:[`C++`,`Rust`,`Go`,`Java`,`Bun`,`PyPy`,`Ruby`,`CPython`,`Node`],datasets:[e({zh:`陣列 512KB`,en:`array 512KB`},[1.47,1.32,1.41,1.35,1,1.02,1.01,1.03,1],`hsl(266 30% 82%)`),e({zh:`陣列 8MB`,en:`array 8MB`},[1.87,2.07,2.06,2.02,1.84,1.97,1.5,1.71,1.02],`hsl(266 38% 70%)`),e({zh:`陣列 64MB`,en:`array 64MB`},[4.82,4.82,4.99,5.02,6.47,6.81,3.7,2.51,2.1],t.wlHash)]},options:m(`x`,1)},conclusion:{zh:`<p>最深那排（陣列 64MB）裡，C++ 亂序讀比順序讀慢 4.82 倍，CPython 只慢 2.51 倍。C++ 一次讀取本來只要 0.77 奈秒，等一次主記憶體就把它變成 3.71 奈秒；CPython 一次讀取本來就要 69.7 奈秒，同樣那段等待攤在它身上看起來小得多。快的語言受到的影響大（C++ 慢 4.82 倍），慢的語言受到的影響小（CPython 慢 2.51 倍），所以語言之間的差距縮小了。</p><p>用跟主表同一個算法（最慢的中位數除以最快的）：<b>順序讀 9 個語言差 90.6 倍，亂序讀只差 47.1 倍</b>，剩下 52%。要解釋的那一段是埃氏篩的 59.3 倍到 hashmap 純查詢的 27.2 倍，剩下 46%。兩個數字幾乎一樣。跑之前寫好的線是「要縮到六成以下才算數」，不是看到 52% 才訂的。換三種別的算跨度的方式，縮小的幅度在 49% 到 87% 之間，方向都一樣。</p><p>三種陣列大小是拿來看快取的。512KB 跟 8MB 都塞得進這台機器 12MB 的 L2，64MB 塞不進。9 個語言的倍數全部隨陣列變大而上升，27 個數字沒有一個逆向。資料愈大、愈多讀取要真的去等主記憶體，亂序就愈貴。</p><p>Node 是圖上唯一沒跟著往上的。陣列 64MB，Node 的順序讀每次 3.75 奈秒、亂序讀 7.87 奈秒，7.87 除以 3.75 就是 2.10。同樣 64MB 的 C++ 是順序 0.77、亂序 3.71，除出來 4.82。亂序讀 Node 比 C++ 慢 2.1 倍（7.87 對 3.71），<b>順序讀慢 4.87 倍</b>。不是亂序對 Node 便宜，是它的順序讀本來就慢，除數大了商就小。</p><p>Node 的順序讀在 512KB 是每次 1.05 奈秒，8MB 變成 3.84，64MB 3.75。同一份 JavaScript 在 Bun 上三種大小都是 1.03 到 1.10 奈秒，完全沒有這個變化。而且這只發生在這種讀法上：這兩個 runtime 跑主表那三題，Node 慢 Bun 1.17 到 1.68 倍，不是 3.5 倍。</p><p>這張圖量的是陣列，不是 hashmap，所以它只證明位址亂跳會讓語言差距縮小。</p><p class="caveat">跨度那條 52% 是照事先寫好的線判的；「資料裝不進快取才會這樣」不是。我原本為它寫的線要求資料在快取裡的話亂序不該多花時間，而 C++ 在 512KB 亂序就慢了 1.47 倍，那條線的前提自己不成立，作廢。27 個數字同向是看完結果才注意到的。</p>`,en:`<p>In the darkest row (array 64MB), the C++ scattered read is 4.82x slower than the sequential read; CPython is only 2.51x slower. One C++ read takes only 0.77 nanoseconds to begin with, and one wait for main memory turns it into 3.71 nanoseconds; one CPython read already takes 69.7 nanoseconds, so the same wait spread over it looks much smaller. The fast language is affected more (C++ 4.82x slower), the slow language less (CPython 2.51x slower), so the gap between languages shrinks.</p><p>With the same calculation as the main table (slowest median divided by fastest): <b>on sequential reads the 9 languages differ by 90.6x, on scattered reads only 47.1x</b>, 52% left. The part to explain is the drop from 59.3x on the sieve to 27.2x on hashmap lookup only, 46% left. The two numbers are almost the same. The line written before the run was "it counts only if it shrinks below 60%", not set after seeing 52%. With three other ways of computing the span, the shrink is between 49% and 87%, all in the same direction.</p><p>The three array sizes are there to look at the cache. 512KB and 8MB both fit in this machine's 12MB L2, 64MB does not. The ratios of all 9 languages rise as the array grows; not one of the 27 numbers goes the other way. The larger the data, the more reads really have to wait for main memory, and the more expensive scattered order gets.</p><p>Node is the only one on the chart that does not rise with the rest. At array 64MB, the Node sequential read is 3.75 nanoseconds each and the scattered read 7.87; 7.87 divided by 3.75 is 2.10. C++ at the same 64MB is 0.77 sequential and 3.71 scattered, which divides to 4.82. On scattered reads Node is 2.1x slower than C++ (7.87 against 3.71); <b>on sequential reads 4.87x slower</b>. It is not that scattered order is cheap for Node; its sequential read is slow to begin with, and a larger divisor gives a smaller quotient.</p><p>The Node sequential read is 1.05 nanoseconds each at 512KB, becomes 3.84 at 8MB, and 3.75 at 64MB. The same JavaScript on Bun is 1.03 to 1.10 nanoseconds at all three sizes, with none of this change. And it happens only with this read pattern: on the three main table workloads, Node is 1.17 to 1.68x slower than Bun, not 3.5x.</p><p>This chart measures an array, not a hashmap, so it only proves that scattered addresses shrink the language gap.</p><p class="caveat">The 52% span was judged against a line written in advance; "this only happens when the data does not fit in cache" was not. The line I had written for it required that scattered order should cost no extra time when the data is in cache, but C++ at 512KB is already 1.47x slower in scattered order, so the premise of that line fails on its own, and it is void. That the 27 numbers all go the same direction was noticed only after seeing the results.</p>`}}]}];export{w as n,v as t};